import React, { useState } from "react";
import "./RegisterScreen.css";
import axios from "axios";
import "@fontsource/ibm-plex-sans";
import "@fontsource/inter";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faEye, faEyeSlash } from "@fortawesome/free-solid-svg-icons";

const RegisterScreen = ({ onBackToLogin, onRegisterSuccess }) => {
  const [formData, setFormData] = useState({
    full_name: "",
    name: "",
    email: "Ikan@gmail.com",
    industry: "Food and Beverages",
    organization: "HKN",
    continent: "Asia",
    objective: "Kemitraan Strategis",
    city: "Kota Bandung",
    phone_number: "",
    password: "",
    confirmPassword: "",
  });

  const [phoneInput, setPhoneInput] = useState("");
  const [errors, setErrors] = useState({});
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  const [showErrorPopup, setShowErrorPopup] = useState(false);
  const [errorMessage, setErrorMessage] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  const triggerErrorPopup = (message) => {
    setErrorMessage(message);
    setShowErrorPopup(true);
    setTimeout(() => setShowErrorPopup(false), 3000);
  };

  const handleChange = (e) => {
    const { name, value } = e.target;

    if (name === "phone_number") {
      let cleanValue = value.replace(/\D/g, "");
      let displayValue = cleanValue;
      let backendValue = cleanValue;

      if (cleanValue.startsWith("628")) {
        displayValue = cleanValue.substring(2);
        backendValue = cleanValue.substring(3);
      } else if (cleanValue.startsWith("08")) {
        displayValue = cleanValue.substring(1);
        backendValue = cleanValue.substring(2);
      } else if (cleanValue.startsWith("8")) {
        displayValue = cleanValue;
        backendValue = cleanValue;
      } else {
        displayValue = cleanValue;
        backendValue = cleanValue;
      }

      setFormData((prev) => ({
        ...prev,
        phone_number: backendValue,
      }));
      setPhoneInput(displayValue);
      setErrors((prev) => ({ ...prev, phone_number: "" }));
    } else {
      setFormData((prev) => ({ ...prev, [name]: value }));
    }
  };

  const validate = () => {
    const newErrors = {};
    const { full_name, name, phone_number, password, confirmPassword } = formData;
    const passwordRegex = /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[\W_]).{8,}$/;

    if (!full_name.trim()) newErrors.full_name = "Nama Lengkap wajib diisi.";
    if (!name.trim()) newErrors.name = "Nama wajib diisi.";
    if (!phone_number.trim()) newErrors.phone_number = "Nomor HP wajib diisi.";

    if (!password.trim()) {
      newErrors.password = "Silakan isi password Anda.";
    } else if (!passwordRegex.test(password)) {
      newErrors.password =
        "Silakan cek password Anda: minimal 8 karakter, 1 huruf kapital, 1 angka, 1 simbol.";
    }

    if (!confirmPassword.trim()) {
      newErrors.confirmPassword = "Silakan konfirmasi password.";
    } else if (confirmPassword !== password) {
      newErrors.confirmPassword = "Password tidak cocok, masukkan kembali password.";
    }

    return newErrors;
  };

  const isFormValid = () => {
    const required = ["full_name", "name", "phone_number", "password", "confirmPassword"];
    return required.every((field) => formData[field]?.trim() !== "");
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const validationErrors = validate();
    setErrors(validationErrors);

    if (Object.keys(validationErrors).length === 0) {
      setIsSubmitting(true); // ⬅️ Tambahkan ini

      try {
        const payload = {
          ...formData,
          phone_number: "62" + formData.phone_number,
          password2: formData.confirmPassword,
        };

        const response = await axios.post("https://geoserver.mapid.io/users/register", payload);

        if (response.status === 201 || response.status === 200) {
          localStorage.setItem("phone_number", "62" + formData.phone_number);
          localStorage.setItem("name", formData.name);
          localStorage.setItem("full_name", formData.full_name);
          alert("Registrasi berhasil! Silakan login.");
          onRegisterSuccess({
            name: formData.name,
            password: formData.password,
            full_name: formData.full_name,
            phone_number: payload.phone_number
          });
        } else {
          triggerErrorPopup(`Registrasi gagal. Status: ${response.status}`);
        }

      } catch (error) {
        const backendErrors = error.response?.data || {};
        const newErrors = {};

        if (backendErrors.name) {
          newErrors.name = backendErrors.name;
          triggerErrorPopup(backendErrors.name);
        }
        if (backendErrors.phone_number) {
          newErrors.phone_number = backendErrors.phone_number;
          triggerErrorPopup(backendErrors.phone_number);
        }
        if (!newErrors.name && !newErrors.phone_number) {
          triggerErrorPopup(backendErrors.message || "Registrasi gagal.");
        }

        setErrors((prev) => ({ ...prev, ...newErrors }));

      } finally {
        setIsSubmitting(false); // ⬅️ Reset setelah selesai
      }
    }
  };


  const renderError = (field) =>
    errors[field] && (
      <div style={{ color: "red", fontSize: "12px", marginTop: "4px" }}>
        {errors[field]}
      </div>
    );

  return (
    <>
      {showErrorPopup && (
        <div className="popup-error">
          {errorMessage}
        </div>
      )}
      <div className="scroll-wrapper">
      <div className="register-container">
        <div className="register-header">
          <button onClick={onBackToLogin} className="back-button1">
            <img src="/kembali.png" alt="Kembali" />
          </button>
        </div>
        <div className="logo-container">
          <img src="/HKN.png" className="logo" id="HKN" alt="HKN" />
          <h2>Daftar</h2>
        </div>
        <h3>Isi Data Diri Anda</h3>
        <form className="register-form" onSubmit={handleSubmit}>
          <label>Nama Lengkap *</label>
          <input
            type="text"
            name="full_name"
            className="register-input"
            placeholder="Masukkan Lengkap Nama Anda"
            value={formData.full_name}
            onChange={handleChange}
          />
          {renderError("full_name")}

          <label>Username *</label>
          <input
            type="text"
            name="name"
            className="register-input"
            placeholder="Masukkan Username Anda"
            value={formData.name}
            onChange={handleChange}
          />
          {renderError("name")}

          <label>Nomor Handphone *</label>
          <div style={{ display: "flex", alignItems: "center" }}>
            <span
              style={{
                padding: "10px",
                border: "1px solid #ccc",
                background: "white",
                borderRadius: "6px 0 0 6px",
                fontSize: "14px",
                height: "20px",
              }}
            >
              +62
            </span>
            <input
              type="tel"
              name="phone_number"
              className="register-input"
              placeholder="Masukkan Nomor Handphone"
              style={{ borderRadius: "0 10px 10px 0", flex: 1 }}
              value={phoneInput}
              onChange={handleChange}
            />
          </div>
          {renderError("phone_number")}

          <label>Buat Password *</label>
          <div className="password-wrapper">
            <input
              type={showPassword ? "text" : "password"}
              name="password"
              className="register-input"
              placeholder="Masukkan Password"
              value={formData.password}
              onChange={handleChange}
            />
            <FontAwesomeIcon
              icon={showPassword ? faEyeSlash : faEye}
              className="eye-icon1"
              onClick={() => setShowPassword(!showPassword)}
            />
          </div>
          {renderError("password")}

          <label>Ulangi Password *</label>
          <div className="password-wrapper">
            <input
              type={showConfirmPassword ? "text" : "password"}
              name="confirmPassword"
              className="register-input"
              placeholder="Ulangi Password"
              value={formData.confirmPassword}
              onChange={handleChange}
            />
            <FontAwesomeIcon
              icon={showConfirmPassword ? faEyeSlash : faEye}
              className="eye-icon1"
              onClick={() => setShowConfirmPassword(!showConfirmPassword)}
            />
          </div>
          {renderError("confirmPassword")}

          <button
            type="submit"
            className="register-button"
            style={{
              backgroundColor: isFormValid() ? "#FFB532" : undefined,
              color: isFormValid() ? "#292B32" : undefined,
              opacity: isSubmitting ? 0.6 : 1, // opsional: efek visual
              cursor: isSubmitting ? "not-allowed" : "pointer",
            }}
            disabled={!isFormValid() || isSubmitting} // ← tambah ini
          >
            {isSubmitting ? "Mendaftar..." : "Daftar"}
          </button>
        </form>
      </div>
      </div>
    </>
  );
};

export default RegisterScreen;
