import React, { useState, useEffect, useMemo } from "react";
import "./DataLengkapScreen.css";

const DataLengkapScreen = ({
  onNext,
  coords,
  onBack,
  goToSection,
  formDataAll,
  setFormDataAll,
}) => {
  const [formData, setFormData] = useState({});

  // ✅ Gunakan useMemo agar tidak berubah-ubah setiap render
const fields = useMemo(() => [
  { label: "Nama Panggilan", name: "c6df1999-8400-4618-9d76-0fa88f3cc07f", type: "text" },
  { label: "Tempat Lahir (Kota/Kab)", name: "d5e67612-8675-40de-b764-2f0a6adf8a26", type: "text" },
  { label: "Tanggal Lahir", name: "e7b93943-5c4c-4d3e-a781-8b3c679bc920", type: "date" },
  {
    label: "Jenis Kelamin",
    name: "3ecb1658-a3ca-40dc-afca-6f84d75829bb",
    type: "select",
    options: ["Laki-laki", "Perempuan"],
  },
  
  {
    label: "Jurusan",
    name: "e613ac12-5bd8-49a7-ad5d-fa77ce798f13",
    type: "select",
    options: ["IPA", "IPS"],
  },
  {
    label: "Angkatan KN",
    name: "4d5d6bf8-16e5-48df-a03c-2df596edacb2", // ganti dengan UUID sesuai database jika ada
    type: "select",
    options: Array.from({ length: 100 }, (_, i) => (i + 1).toString()),
  },
], []);


  // ✅ Preload jika data sudah ada di formDataAll (agar field terisi kembali)
  useEffect(() => {
    const initialData = {};
    fields.forEach((field) => {
      initialData[field.name] = formDataAll?.feature?.properties?.[field.name] || "";
    });
    setFormData(initialData);
  }, [fields, formDataAll]);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleNext = () => {
    const requiredUUIDs = fields.map((f) => f.name);
    const isEmpty = requiredUUIDs.some((uuid) => !formData[uuid]?.toString().trim());

    if (isEmpty) {
      alert("Mohon lengkapi semua isian wajib.");
      return;
    }

    const updatedAll = {
      ...formDataAll,
      feature: {
        type: "Feature",
        geometry: coords
          ? {
              type: "Point",
              coordinates: [coords[0], coords[1]],
            }
          : formDataAll?.feature?.geometry || null,
        properties: {
          ...(formDataAll?.feature?.properties || {}),
          ...formData, // tambahkan/update data section 1
        },
      },
    };

    console.log("✅ Data Terkumpul Section 1:", updatedAll.feature.properties);
    setFormDataAll(updatedAll);
    onNext();
  };

  return (
    <div className="data-lengkap-container">
      <div className="geo-header1">
        <button onClick={onBack} className="geo-back1-button">
          <img src="/kembali.png" alt="Kembali" />
        </button>
      </div>

      {/* Bulatan Section 1-5 */}
      <div className="section-buttons">
        {[1, 2, 3, 4, 5].map((num) => (
          <button
            key={num}
            onClick={() => goToSection(num)}
            className={`circle-button ${num === 1 ? "active" : ""}`}
          >
            {num}
          </button>
        ))}
      </div>

      {/* Judul */}
      <div className="section-title">
        <img src="/HKN.png" className="logo7" id="HKN" alt="HKN" />
        <h2>Data Pribadi</h2>
        <span className="section-subtitle">Section 1/5</span>
      </div>

      {/* Form Input */}
      <div className="form-section">
        {fields.map((field) => (
          <div key={field.name} className="input-box">
            <label className="input-label">{field.label}</label>
            <p className="required-text">Wajib diisi</p>
            {field.type === "select" ? (
              <select
                name={field.name}
                value={formData[field.name] || ""}
                onChange={handleChange}
                className="form-input"
              >
                <option value="">Pilih</option>
                {field.options.map((option) => (
                  <option key={option} value={option}>
                    {option}
                  </option>
                ))}
              </select>
            ) : (
              <input
                type={field.type}
                name={field.name}
                value={formData[field.name] || ""}
                onChange={handleChange}
                className="form-input"
              />
            )}
          </div>
        ))}
      </div>

      {/* Tombol Lanjut */}
      <div className="form-footer">
        <button className="next-button" onClick={handleNext}>
          Next page
        </button>
      </div>
    </div>
  );
};

export default DataLengkapScreen;
