import React, { useState, useEffect, useMemo } from "react";
import "./DataLengkapScreen2.css";

const DataLengkapScreen2 = ({
  onBack,
  onNext,
  goToSection,
  formDataAll,
  setFormDataAll,
}) => {
  const [formData, setFormData] = useState({});

  // Gunakan useMemo agar tidak memicu warning React
  const fields = useMemo(
    () => [
      {
        label: "Kota Domisili",
        name: "e626de93-de37-4976-b5b1-735d81ad944e",
        type: "datalist",
        options: ["Kota Bandung", "Kota Bekasi"],
        placeholder: "Contoh: Kota Bandung",
      },
      {
        label: "Alamat Lengkap Domisili",
        name: "a14ae29e-4c15-4064-b23e-4448d0dc341d",
        type: "textarea",
        placeholder: "Tulis alamat lengkap jika ada",
      },
    ],
    []
  );

  // Set ulang formData berdasarkan formDataAll saat halaman ini dimuat
  useEffect(() => {
    const initialData = {};
    fields.forEach((field) => {
      initialData[field.name] =
        formDataAll?.feature?.properties?.[field.name] || "";
    });
    setFormData(initialData);
  }, [fields, formDataAll]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleNext = () => {
    const updatedAll = {
      ...formDataAll,
      feature: {
        ...formDataAll.feature,
        type: "Feature",
        geometry: formDataAll?.feature?.geometry || null,
        properties: {
          ...(formDataAll?.feature?.properties || {}),
          ...formData,
        },
      },
    };

    console.log("✅ Data Terkumpul di Section 2:", updatedAll.feature.properties);
    setFormDataAll(updatedAll);
    onNext();
  };

  return (
    <div className="data-lengkap2-container">
      <div className="geo-header1">
        <button onClick={onBack} className="geo-back1-button">
          <img src="/kembali.png" alt="Kembali" />
        </button>
      </div>

      <div className="section-buttons">
        {[1, 2, 3, 4, 5].map((num) => (
          <button
            key={num}
            onClick={() => goToSection(num)}
            className={`circle-button ${num === 2 ? "active" : ""}`}
          >
            {num}
          </button>
        ))}
      </div>

      <div className="section-title">
        <h2>Data Domisili</h2>
        <span className="section-subtitle">Section 2/5</span>
      </div>

      <div className="form-section2">
        {fields.map((field) => (
          <div key={field.name} className="input-box2">
            <label className="input-label2">{field.label}</label>
            <p className="required-text2">Wajib diisi</p>
            {field.type === "datalist" ? (
              <>
                <input
                  type="text"
                  list={`list-${field.name}`}
                  name={field.name}
                  value={formData[field.name] || ""}
                  onChange={handleChange}
                  className="form-input2"
                  placeholder={field.placeholder}
                />
                <datalist id={`list-${field.name}`}>
                  {field.options.map((option) => (
                    <option key={option} value={option} />
                  ))}
                </datalist>
              </>
            ) : field.type === "textarea" ? (
              <textarea
                name={field.name}
                value={formData[field.name] || ""}
                onChange={handleChange}
                className="form-input2"
                placeholder={field.placeholder}
                rows={4}
              />
            ) : (
              <input
                type={field.type}
                name={field.name}
                value={formData[field.name] || ""}
                onChange={handleChange}
                className="form-input2"
              />
            )}
          </div>
        ))}
      </div>

      <div className="form-footer">
        <button className="next-button" onClick={handleNext}>
          Next page
        </button>
      </div>
    </div>
  );
};

export default DataLengkapScreen2;
