import React, { useEffect, useState, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import './Home.css';
import { Home as HomeIcon, Users, MessageCircle, User, Clock } from 'react-feather';
import axios from 'axios';

const Home = () => {
  const navigate = useNavigate();
  const [user, setUser] = useState({
    nama: 'Loading...',
    kota: 'Loading...',
    foto: './no-profile.jpg'
  });
  const [kegiatanList, setKegiatanList] = useState([]);
  const [tampilkanSemua, setTampilkanSemua] = useState(false);
  const [currentSlide, setCurrentSlide] = useState(0);
  const heroScrollRef = useRef(null);

  useEffect(() => {
    const storedUser = localStorage.getItem("user");
    if (!storedUser) return;

    const parsedUser = JSON.parse(storedUser);
    const username = parsedUser.name;

    const layerId = '6804f7733996df0058de7279';
    const projectId = '67fddd3d7df91cc4425c7fba';
    const skip = 0;
    const limit = 100000000;

    fetch(`https://geoserver.mapid.io/moneys_bun/v2/get_layer_detail_by_id/${layerId}/${projectId}?skip=${skip}&limit=${limit}`)
      .then(res => res.json())
      .then(async (data) => {
        if (!Array.isArray(data)) return;

        const userFeature = data.find(item =>
          item.properties?.["257cab30-92f4-4ba9-a44f-3fee07656b6c"] === username
        );

        if (userFeature) {
          const props = userFeature.properties || {};
          const featureKey = userFeature.key;
          const jwt = localStorage.getItem("jwt");

          // Dapatkan lokasi live dari browser
          if (navigator.geolocation) {
            navigator.geolocation.getCurrentPosition(async (position) => {
              const lat = position.coords.latitude;
              const lng = position.coords.longitude;

              // Ambil nama kota via reverse geocoding
              let cityName = "-";
              try {
                const res = await fetch(`https://nominatim.openstreetmap.org/reverse?lat=${lat}&lon=${lng}&format=json`);
                const data = await res.json();
                cityName = data.address.city || data.address.county || "Tidak Diketahui";
              } catch (err) {
                console.error("Reverse geocoding gagal:", err);
              }

              // Update ke server
              try {
                await axios.post("https://geoserver.mapid.io/layers/v2/edit_geometry", {
                  feature_key: featureKey,
                  geo_layer_id: layerId,
                  geometry: {
                    type: "Point",
                    coordinates: [lng, lat]
                  }
                }, {
                  headers: { accesstoken: jwt }
                });

                await axios.post("https://geoserver.mapid.io/layers/v2/edit_properties", {
                  feature_key: featureKey,
                  geo_layer_id: layerId,
                  properties_key: "7248ec10-1352-4080-a707-dfc9fa2d2325",
                  properties_value: cityName
                }, {
                  headers: { accesstoken: jwt }
                });

                setUser({
                  nama: props["b248e4a2-d648-44e1-9ef4-7401539c0ab0"] || parsedUser.full_name || "Anonim",
                  kota: cityName,
                  foto: props["658b0f25-1f76-4219-bf8b-fafecefa87bd"] || `https://i.pravatar.cc/150?u=${username}`
                });
              } catch (err) {
                console.error("Gagal update lokasi:", err);
              }
            });
          }}
      })
      .catch(console.error);

    // Kegiatan seperti biasa
    fetch('https://geoserver.mapid.io/layers_new/get_layer?api_key=933cb5f2fe89479b8b692a1f8f406639&layer_id=6837ebe8c0529a72940f17a4&project_id=67fddd3d7df91cc4425c7fba')
      .then(res => res.json())
      .then((geojson) => {
        const data = geojson.features.map((item) => {
          const props = item.properties || {};
          const coords = item.geometry?.coordinates || [null, null];
          return {
            id: item.id,
            judul: props["Nama Kegiatan"],
            deskripsi: props["Deskripsi"],
            tanggal: props["Tanggal"],
            jam: props["Jam"],
            gambar: props["Poster Kegiatan"],
            galeri: [
              props["Foto tambahan 1"],
              props["Foto tambahan 2"],
              props["Foto tambahan 3"]
            ].filter(Boolean),
            lat: coords[1],
            lng: coords[0]
          };
        });

        setKegiatanList(data);
      })
      .catch(console.error);
  }, []);

  const formatTanggal = (tgl) =>
    new Date(tgl).toLocaleDateString('id-ID', {
      day: 'numeric',
      month: 'long',
      year: 'numeric'
    });

  const handleScroll = () => {
    const scrollLeft = heroScrollRef.current.scrollLeft;
    const width = heroScrollRef.current.offsetWidth;
    const index = Math.round(scrollLeft / width);
    setCurrentSlide(index);
  };

  return (
    <div className="home-container">
      {/* Header Full Width */}
      <div className="home-header">
        <img src="/User.png" alt="Logo" className="logo" />
        <div className="spacer" />
        <div className="header-user-info">
          <div className="location-text">📍 {user.kota}</div>
          <div className="hi-text">Hi, {user.nama.split(',')[0]}</div>
        </div>
        <img src={user.foto} alt="User" className="user-photo" />
      </div>

      {/* Hero Section Carousel */}
      {kegiatanList.length > 0 && (
        <div className="section">
          <h3>Foto Kegiatan</h3>
          <p>Jangan lewatkan momen berkesan ...</p>

          <div ref={heroScrollRef} onScroll={handleScroll} className="hero-carousel">
            {kegiatanList.slice(0, 3).map((item, i) => (
              <div key={i} className="hero-slide">
                <img
                  src={item.gambar + '?w=800&h=400&fit=crop'}
                  alt={`Hero ${i}`}
                  className="hero-img"
                  loading="lazy"
                />
                <div className="hero-caption">
                  <h3 style={{ fontWeight: 'bold', maxWidth: '90%', margin: '0 auto 4px auto', textAlign: 'center' }}>{item.judul}</h3>
                  <p style={{ maxWidth: '90%', fontSize: '0.9rem', color: '#ddd', margin: '0 auto 8px auto', textAlign: 'center', overflow: 'hidden', textOverflow: 'ellipsis', display: '-webkit-box', WebkitLineClamp: 2, WebkitBoxOrient: 'vertical' }}>{item.deskripsi}</p>
                  <button className="cta-button" onClick={() => navigate(`/kegiatan/${item.id}`)}>Lihat Detail</button>
                </div>
              </div>
            ))}
          </div>

          {/* Titik indikator */}
          <div style={{ display: 'flex', justifyContent: 'center', marginTop: '10px', gap: '6px' }}>
            {[...Array(3)].map((_, i) => (
              <div key={i} style={{ width: 10, height: 10, borderRadius: '50%', backgroundColor: i === currentSlide ? '#facc15' : '#ccc' }} />
            ))}
          </div>
        </div>
      )}

      {/* Kegiatan Mendatang */}
      <div className="section">
        <h3>Kegiatan Mendatang</h3>
        <p>Ada yang seru bakal datang!</p>
        <ul className="event-list">
          {(tampilkanSemua ? kegiatanList : kegiatanList.slice(0, 3)).map((event, i) => (
            <li key={i} className="event-card" onClick={() => navigate(`/kegiatan/${event.id}`)} style={{ cursor: 'pointer' }}>
              <img src={event.gambar + '?w=400&h=300&fit=crop'} alt="thumb" loading="lazy" />
              <div>
                <strong>{event.judul}</strong>
                <p style={{ display: 'flex', alignItems: 'center', gap: '4px', fontSize: '0.9rem', color: '#555' }}>
                  <Clock size={16} />
                  {formatTanggal(event.tanggal)}
                </p>
              </div>
            </li>
          ))}
        </ul>

        {!tampilkanSemua && kegiatanList.length > 3 && (
          <button className="cta-button" style={{ marginTop: '1rem' }} onClick={() => setTampilkanSemua(true)}>
            Lihat Kegiatan Lainnya
          </button>
        )}
      </div>

      {/* Bottom Navigation */}
      <div className="bottom-nav">
        <button className="nav-btn active">
          <HomeIcon size={22} />
          <span className="nav-label">Beranda</span>
        </button>
        <button className="nav-btn" onClick={() => navigate('/dashboard')}>
          <Users size={22} />
          <span className="nav-label">Alumni</span>
        </button>
        <button className="nav-btn" onClick={() => navigate('/chat')}>
          <MessageCircle size={22} />
          <span className="nav-label">Chat</span>
        </button>
        <button className="nav-btn" onClick={() => navigate('/profile')} aria-label="Buka Halaman Chat">
          <User size={22} />
          <span className="nav-label">Profil</span>
        </button>
      </div>
    </div>
  );
};

export default Home;
