import React, { useEffect, useState, useRef } from "react";
import axios from "axios";
import "./UbahSemuaPropertiForm.css";
import { useNavigate } from "react-router-dom";
import maplibregl from "maplibre-gl";
import "maplibre-gl/dist/maplibre-gl.css";

const layerId = "6804f7733996df0058de7279";
const projectId = "67fddd3d7df91cc4425c7fba";
const usernameFieldKey = "257cab30-92f4-4ba9-a44f-3fee07656b6c";
const fotoFieldKey = "658b0f25-1f76-4219-bf8b-fafecefa87bd";

const fieldConfig = [
  { label: "Tempat Lahir (Kota/Kab)", name: "d5e67612-8675-40de-b764-2f0a6adf8a26", type: "text" },
  { label: "Tanggal Lahir", name: "e7b93943-5c4c-4d3e-a781-8b3c679bc920", type: "date" },
  { label: "Jenis Kelamin", name: "3ecb1658-a3ca-40dc-afca-6f84d75829bb", type: "select", options: ["Laki-laki", "Perempuan"] },
  { label: "Angkatan", name: "4d5d6bf8-16e5-48df-a03c-2df596edacb2", type: "select", options: Array.from({ length: 100 }, (_, i) => (i + 1).toString()) },
  { label: "Jurusan", name: "e613ac12-5bd8-49a7-ad5d-fa77ce798f13", type: "select", options: ["IPA", "IPS"] },
  { label: "Kota Domisili", name: "e626de93-de37-4976-b5b1-735d81ad944e", type: "datalist", options: ["Kota Bandung", "Kota Bekasi"], placeholder: "Contoh: Kota Bandung" },
  { label: "Alamat Lengkap Domisili", name: "a14ae29e-4c15-4064-b23e-4448d0dc341d", type: "textarea", placeholder: "Tulis alamat lengkap jika ada" },
  { label: "Universitas / Sekolah Lanjutan", name: "f83df530-9b7c-4a45-ad7c-2678b024612e", type: "datalist", options: ["Universitas Indonesia (UI)", "Institut Teknologi Bandung (ITB)"] },
  { label: "Jurusan", name: "5e5eb224-a5a0-45b9-aa99-8190c97eb454", type: "datalist", options: ["Teknik Sipil", "Teknik Arsitektur"] },
  { label: "Gelar", name: "def0c6cd-fa51-4b85-a627-5951c47b225c", type: "datalist", options: ["A.P.", "A.Ma."] },
  { label: "Profesi / Jabatan", name: "ae6eefea-caf6-4750-97cf-db4afb890235", type: "datalist", options: ["Pelajar/Mahasiswa", "Dosen"], placeholder: "Contoh: Pelajar/Mahasiswa" },
  { label: "Instansi / Perusahaan", name: "c7193f90-f88f-420d-ad69-a1936ce86881", type: "datalist", options: ["Pemerintah Pusat", "Pemerintah Provinsi"], placeholder: "Contoh: Pemerintah Pusat" },
  { label: "Bidang / Industri", name: "ddc6cd90-6be8-4ddd-ba9f-d45ae265eb77", type: "datalist", options: ["Pemerintahan", "Militer / Kepolisian"], placeholder: "Contoh: Pemerintahan" },
  { label: "Kota/Kabupaten Tempat Bekerja", name: "7248ec10-1352-4080-a707-dfc9fa2d2325", type: "datalist", options: ["Jakarta Pusat", "Jakarta Barat"], placeholder: "Contoh: Jakarta Pusat" },
  { label: "Apakah bersedia terlibat kegiatan HKN?", name: "be92ce14-e5f6-403e-9696-596a8b570d35", type: "select", options: ["Ya", "Tidak"] },
  { label: "Minat dan Kontribusi", name: "6e0a4fed-4131-44d5-b7ff-f489087a6061", type: "datalist", options: ["Networking", "Donasi"], placeholder: "Contoh: Lingkungan, Pendidikan, dll." },
  { label: "Link Sosial Media", name: "bd45ee2b-adce-4165-aed6-d45db44fb818", type: "text", placeholder: "Masukkan tautan profil sosial media" },
  { label: "Foto Diri (opsional)", name: fotoFieldKey, type: "file" },
  { label: "Cerita Kenangan Menarik di Krida (opsional)", name: "97e0bf48-4a30-40c6-83ec-6e768d622ea0", type: "textarea", placeholder: "Ceritakan pengalaman berkesanmu di Krida" },
  { label: "NIS", name: "6f029f2e-5744-4d4d-82b4-77441b3c1fb3", type: "text", placeholder: "Masukkan Nomor Induk Siswa" },
];

const UbahSemuaPropertiForm = () => {
  const [formData, setFormData] = useState({ latitude: "-2.5", longitude: "118.5" });
  const [fotoFile, setFotoFile] = useState(null);
  const [username, setUsername] = useState("");
  const [accessToken, setAccessToken] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const navigate = useNavigate();
  const mapRef = useRef(null);
  const markerRef = useRef(null);
  const mapContainerRef = useRef(null);

  useEffect(() => {
    const user = JSON.parse(localStorage.getItem("user") || "{}");
    const jwt = localStorage.getItem("jwt");
    setAccessToken(jwt || "");
    setUsername(user.username_id || user.name || "");
  }, []);

  useEffect(() => {
    if (!username) return;

    const fetchData = async () => {
      const res = await axios.get(`https://geoserver.mapid.io/moneys_bun/v2/get_layer_detail_by_id/${layerId}/${projectId}?skip=0&limit=1000`);
      const found = res.data.find((d) => d.properties?.[usernameFieldKey] === username);
      if (found) {
        setFormData({
          ...found.properties,
          latitude: found.geometry?.coordinates?.[1]?.toString() || "-2.5",
          longitude: found.geometry?.coordinates?.[0]?.toString() || "118.5"
        });
        localStorage.setItem("feature_key", found.key);
      }
    };
    fetchData();
  }, [username]);

  useEffect(() => {
    const lat = parseFloat(formData.latitude);
    const lng = parseFloat(formData.longitude);
    if (isNaN(lat) || isNaN(lng)) return;

    if (!mapRef.current && mapContainerRef.current) {
      mapRef.current = new maplibregl.Map({
        container: mapContainerRef.current,
        style: `https://basemap.mapid.io/styles/basic/style.json?key=67b6a6056fb80e64559cc07e`,
        center: [lng, lat],
        zoom: 13,
      });

      markerRef.current = new maplibregl.Marker({ draggable: true })
        .setLngLat([lng, lat])
        .addTo(mapRef.current);

      markerRef.current.on("dragend", () => {
        const { lat, lng } = markerRef.current.getLngLat();
        setFormData((prev) => ({ ...prev, latitude: lat.toString(), longitude: lng.toString() }));
      });
    } else if (markerRef.current) {
      markerRef.current.setLngLat([lng, lat]);
      mapRef.current?.flyTo({ center: [lng, lat], zoom: 13 });
    }
  }, [formData.latitude, formData.longitude]);

  const handleChange = (e) => {
    const { name, value, files } = e.target;
    if (files && files.length > 0) {
      setFotoFile(files[0]);
    } else {
      setFormData((prev) => ({ ...prev, [name]: value }));
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);
    const featureKey = localStorage.getItem("feature_key");

    let fotoUrl = formData[fotoFieldKey] || "";
    if (fotoFile) {
      const uploadForm = new FormData();
      uploadForm.append("file", fotoFile);
      uploadForm.append("type", "general_image");

      try {
        const res = await axios.post("https://geoserver.mapid.io/upload", uploadForm, {
          headers: {
            accesstoken: accessToken,
            "Content-Type": "multipart/form-data"
          }
        });
        fotoUrl = res.data?.data?.Location || fotoUrl;
      } catch (err) {
        console.error("❌ Gagal upload foto:", err);
      }
    }

    const finalData = {
      ...formData,
      [fotoFieldKey]: fotoUrl,
      [usernameFieldKey]: username
    };

    const tidakBisaDiubah = [
      "257cab30-92f4-4ba9-a44f-3fee07656b6c",
      "599ee1ae-0fe8-498c-aa19-ccf3d72e4683",
      "b248e4a2-d648-44e1-9ef4-7401539c0ab0",
      "c6df1999-8400-4618-9d76-0fa88f3cc07f"
    ];

    for (const [key, value] of Object.entries(finalData)) {
      if (tidakBisaDiubah.includes(key)) continue;
      try {
        await axios.post("https://geoserver.mapid.io/layers/v2/edit_properties", {
          feature_key: featureKey,
          geo_layer_id: layerId,
          properties_key: key,
          properties_value: value
        }, {
          headers: { accesstoken: accessToken }
        });
      } catch (err) {
        console.error(`❌ Gagal simpan data [${key}]:`, err.response?.data || err);
      }
    }

    // Simpan koordinat geometry
    try {
      await axios.post("https://geoserver.mapid.io/layers/v2/edit_geometry", {
        feature_key: featureKey,
        geo_layer_id: layerId,
        geometry: {
          type: "Point",
          coordinates: [parseFloat(formData.longitude), parseFloat(formData.latitude)]
        }
      }, {
        headers: { accesstoken: accessToken }
      });
    } catch (err) {
      console.error("❌ Gagal simpan lokasi:", err.response?.data || err);
    }

    alert("✅ Semua data berhasil disimpan!");
    setIsSubmitting(false);
    navigate("/profile");
  };

  return (
    <div className="dl5-container">
      <div className="header-flex" style={{ display: "flex", alignItems: "center", gap: "1rem", marginBottom: "1.5rem" }}>
        <button onClick={() => navigate("/profile")} className="back-btn" style={{ background: "none", border: "none", fontSize: "2rem", cursor: "pointer", color: "#333", lineHeight: 1 }}>‹</button>
        <h1 className="title" style={{ fontSize: "1.5rem", fontWeight: "bold", margin: 0 }}>Ubah Data Alumni</h1>
      </div>
      <form onSubmit={handleSubmit} className="dl5-form-section">
        {fieldConfig.map((field) => {
          const value = formData[field.name] || "";
          if (!field.name) return null;

          return (
            <div key={field.name} className="dl5-input-box">
              <label className="dl5-input-label">{field.label}</label>
              {field.type === "select" && (
                <select name={field.name} value={value} onChange={handleChange} className="dl5-form-input">
                  <option value="">-- Pilih --</option>
                  {field.options.map((opt) => <option key={opt} value={opt}>{opt}</option>)}
                </select>
              )}
              {field.type === "datalist" && (
                <>
                  <input list={field.name} name={field.name} value={value} onChange={handleChange} className="dl5-form-input" placeholder={field.placeholder} />
                  <datalist id={field.name}>
                    {field.options.map((opt) => <option key={opt} value={opt} />)}
                  </datalist>
                </>
              )}
              {field.type === "textarea" && (
                <textarea name={field.name} value={value} onChange={handleChange} className="dl5-form-input" placeholder={field.placeholder} />
              )}
              {field.type === "file" && (
                <>
                  <input type="file" accept="image/*" onChange={handleChange} className="dl5-form-input" />
                  {formData[fotoFieldKey] && <img src={formData[fotoFieldKey]} alt="preview" style={{ marginTop: 10, width: 120, borderRadius: 10 }} />}
                </>
              )}
              {field.type === "text" && (
                <input type="text" name={field.name} value={value} onChange={handleChange} className="dl5-form-input" placeholder={field.placeholder} />
              )}
              {field.type === "date" && (
                <input type="date" name={field.name} value={value} onChange={handleChange} className="dl5-form-input" />
              )}
            </div>
          );
        })}
        <div ref={mapContainerRef} style={{ height: 300, borderRadius: 8, marginTop: 20, marginBottom: 20 }} />
        <div className="dl5-form-footer">
          <button type="submit" className="dl5-submit-button" disabled={isSubmitting}>
            {isSubmitting ? "Menyimpan..." : "Simpan Perubahan"}
          </button>
        </div>
      </form>
    </div>
  );
};

export default UbahSemuaPropertiForm;
