import React, { useEffect, useState } from 'react';
import './Dashboardalumni.css';
import { Users, Search, ChevronRight, User, Home, MessageCircle } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

const perPageGroup = 10;
const perPageAlumni = 25;

const App = () => {
  const navigate = useNavigate();
  const [searchTerm, setSearchTerm] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [selectedGroup, setSelectedGroup] = useState(null);
  const [semuaAlumni, setSemuaAlumni] = useState([]);

  useEffect(() => {
    const accessToken = 'eyJhbGciOiJIUzI1NiJ9...'; // Token kamu
    const layerId = '6804f7733996df0058de7279';
    const projectId = '67fddd3d7df91cc4425c7fba';

    fetch(`https://geoserver.mapid.io/moneys_bun/v2/get_layer_detail_by_id/${layerId}/${projectId}?skip=0&limit=1000`, {
      method: 'GET',
      headers: {
        'accept': '*/*',
        'accesstoken': accessToken
      }
    })
      .then(res => res.json())
      .then(data => {
        if (!Array.isArray(data)) {
          console.error('Data tidak valid:', data);
          return;
        }

        const alumni = data.map((item, index) => {
          const props = item.properties || {};
          const angkatanNumber = props["4d5d6bf8-16e5-48df-a03c-2df596edacb2"] || 999;
          return {
            id: item._id,
            name: props["b248e4a2-d648-44e1-9ef4-7401539c0ab0"] || "Tanpa Nama",
            kota: props["d5e67612-8675-40de-b764-2f0a6adf8a26"] || "-",
            pekerjaan: props["ddc6cd90-6be8-4ddd-ba9f-d45ae265eb77"] || "-",
            badge: `Krida Nusantara ${angkatanNumber}`,
            avatarUrl: props["658b0f25-1f76-4219-bf8b-fafecefa87bd"] || "",
            lat: item.geometry?.coordinates?.[1] || null,
            lng: item.geometry?.coordinates?.[0] || null,
            initials: (props["c6df1999-8400-4618-9d76-0fa88f3cc07f"] || "ALM").substring(0, 3).toUpperCase(),
            angkatanNumber,
            color: ['#ffc107', '#4caf50', '#03a9f4'][index % 3]
          };
        });

        alumni.sort((a, b) => a.angkatanNumber - b.angkatanNumber);
        setSemuaAlumni(alumni);
      })
      .catch(err => console.error('Gagal fetch dari MAPID:', err));
  }, []);

  const alumniGroups = [...new Set(semuaAlumni.map((a) => a.badge))].sort((a, b) => {
    const numA = parseInt(a.match(/\d+/));
    const numB = parseInt(b.match(/\d+/));
    return numA - numB;
  });

  const itemsPerPage = selectedGroup ? perPageAlumni : perPageGroup;

  // Filter sebelum paginasi
  const filteredBeforePagination = selectedGroup
    ? semuaAlumni.filter(
        (a) =>
          a.badge === selectedGroup &&
          a.name.toLowerCase().includes(searchTerm.toLowerCase())
      )
    : alumniGroups.filter((group) => {
        const groupMatch = group.toLowerCase().includes(searchTerm.toLowerCase());
        const matchInGroup = semuaAlumni.some(
          (a) =>
            a.badge === group &&
            a.name.toLowerCase().includes(searchTerm.toLowerCase())
        );
        return groupMatch || matchInGroup;
      });

  const totalPages = Math.ceil(filteredBeforePagination.length / itemsPerPage);

  const filteredList = filteredBeforePagination.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage
  );

  const goBack = () => {
    setSelectedGroup(null);
    setCurrentPage(1);
    setSearchTerm('');
  };

  const getPagination = () => {
    const pages = [];
    const maxButtons = 4;
    let start = Math.max(1, currentPage - Math.floor(maxButtons / 2));
    let end = start + maxButtons - 1;
    if (end > totalPages) {
      end = totalPages;
      start = Math.max(1, end - maxButtons + 1);
    }
    for (let i = start; i <= end; i++) {
      pages.push(i);
    }
    return pages;
  };

  return (
    <div className="container">
      <div className="header-flex">
        {selectedGroup && (
          <button className="back-btn" onClick={goBack}>‹</button>
        )}
        <h1 className="title">{selectedGroup || 'Directory Alumni'}</h1>
      </div>

      <div className="search-wrapper">
        <div className="search-input">
          <Search className="search-icon" size={20} />
          <input
            type="text"
            placeholder="Cari..."
            value={searchTerm}
            onChange={(e) => {
              setSearchTerm(e.target.value);
              setCurrentPage(1);
            }}
            className="input"
          />
        </div>
      </div>

      <div className={`list fade-transition ${selectedGroup ? 'fade-in' : 'fade-out'}`}>
        {filteredList.map((item, index) => (
          <div
            key={index}
            className="list-item"
            onClick={() => {
              if (!selectedGroup) {
                setSelectedGroup(item);
                setCurrentPage(1); // Reset saat masuk grup
              } else {
                navigate(`/alumni/${item.id}`);
              }
            }}
          >
            {selectedGroup ? (
              <>
                <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                  {item.avatarUrl ? (
                    <img
                      src={item.avatarUrl || '/no-profile.jpg'}
                      alt={item.name}
                      style={{ width: 32, height: 32, borderRadius: '50%' }}
                    />
                  ) : (
                    <div style={{
                      width: 32,
                      height: 32,
                      borderRadius: '50%',
                      backgroundColor: item.color,
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      color: '#fff',
                      fontSize: 14,
                      fontWeight: 'bold'
                    }}>
                      {item.initials}
                    </div>
                  )}
                  {item.name}
                </div>
                <span style={{
                  background: '#eee',
                  padding: '2px 8px',
                  borderRadius: '10px',
                  fontSize: '12px'
                }}>
                  {item.pekerjaan}
                </span>
              </>
            ) : (
              <>
                {item}
                <ChevronRight size={20} className="chevron" />
              </>
            )}
          </div>
        ))}
      </div>

      <div className="pagination">
        <button
          className="page-btn"
          onClick={() => setCurrentPage((prev) => Math.max(1, prev - 1))}
          disabled={currentPage === 1}
        >
          &lt;
        </button>

        {getPagination().map((page) => (
          <button
            key={page}
            className={`page-btn ${currentPage === page ? 'active' : ''}`}
            onClick={() => setCurrentPage(page)}
          >
            {page}
          </button>
        ))}

        <button
          className="page-btn"
          onClick={() => setCurrentPage((prev) => Math.min(totalPages, prev + 1))}
          disabled={currentPage === totalPages}
        >
          &gt;
        </button>
      </div>

      <div className="bottom-nav">
        <button className="nav-btn" onClick={() => navigate('/home')}>
          <Home size={22} />
          <span className="nav-label">Home</span>
        </button>
        <button className="nav-btn active">
          <Users size={22} />
          <span className="nav-label">Alumni</span>
        </button>
        <button className="nav-btn" onClick={() => navigate('/chat')}>
          <MessageCircle size={22} />
          <span className="nav-label">Chat</span>
        </button>
        <button className="nav-btn" onClick={() => navigate('/profile')}>
          <User size={22} />
          <span className="nav-label">Profil</span>
        </button>
      </div>
    </div>
  );
};

export default App;
