import React, { useState, useEffect } from "react";
import axios from "axios";
import "./LoginScreen.css";
import "@fontsource/inter";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faEye, faEyeSlash } from "@fortawesome/free-solid-svg-icons";
import { useNavigate } from "react-router-dom";

const LoginScreen = ({ onRegister, onLoginSuccess, prefilledLogin, onForgetPassword }) => {
  const [name, setName] = useState("");
  const [password, setPassword] = useState("");
  const [nameError, setNameError] = useState("");
  const [passwordError, setPasswordError] = useState("");
  const [showSuccessPopup, setShowSuccessPopup] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);

  const navigate = useNavigate();

  useEffect(() => {
    if (prefilledLogin) {
      setName(prefilledLogin.name || "");
      setPassword(prefilledLogin.password || "");
    }
  }, [prefilledLogin]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setNameError("");
    setPasswordError("");
    setIsLoading(true);
    localStorage.removeItem("user");
    localStorage.removeItem("jwt");

    try {
      const response = await axios.post("https://geoserver.mapid.io/auth_bun/login", {
        name,
        password,
      });

      if (response.status === 200) {
        const { token, user } = response.data;
        localStorage.setItem("jwt", token);

        const layerId = "6804f7733996df0058de7279";
        const projectId = "67fddd3d7df91cc4425c7fba";

        const alumniLayerRes = await axios.get(
          `https://geoserver.mapid.io/moneys_bun/v2/get_layer_detail_by_id/${layerId}/${projectId}?skip=0&limit=100`
        );

        const alumni = alumniLayerRes.data.find(
          (item) =>
            item.properties?.["257cab30-92f4-4ba9-a44f-3fee07656b6c"]?.toLowerCase() ===
            user.name.toLowerCase()
        );

        if (alumni) {
          const properties = alumni.properties;
          localStorage.setItem(
            "user",
            JSON.stringify({
              name: user.name,
              full_name: user.full_name,
              username_id: properties["257cab30-92f4-4ba9-a44f-3fee07656b6c"] || user.name,
              nama_lengkap: properties["b248e4a2-d648-44e1-9ef4-7401539c0ab0"] || "",
              kota: properties["7248ec10-1352-4080-a707-dfc9fa2d2325"] || "",
              foto: properties["658b0f25-1f76-4219-bf8b-fafecefa87bd"] || "",
              key: alumni.key,
            })
          );
        }

        if (user.is_whatsapp_confirm === "success") {
          navigate("/home");
        } else if (!alumni) {
          navigate("/lengkapi-data");
        } else {
          navigate("/verifikasi-wa");
        }

        setShowSuccessPopup(true);
        setTimeout(() => setShowSuccessPopup(false), 3000);
        onLoginSuccess(token);
      } else {
        setNameError("Nama atau kata sandi yang Anda masukkan salah.");
        setPasswordError("Nama atau kata sandi yang Anda masukkan salah.");
      }
    } catch (error) {
      const msg = error.response?.data?.message || "Login gagal.";
      console.error("Login error:", msg);
      setNameError("Nama atau username yang Anda masukkan salah.");
      setPasswordError("Kata sandi yang Anda masukkan salah.");
    } finally {
      setIsLoading(false);
    }
  };

  const isFormValid = name.trim() !== "" && password.trim() !== "";

  return (
    <>
      {showSuccessPopup && <div className="popup-success">Login Berhasil</div>}
      <div className="login-wrapper">
        <div className="login-container">
          <img src="/HKN.png" className="HKN" alt="HKN" />
          <h2 className="login-title">Masuk</h2>
          <form className="login-form" onSubmit={handleSubmit}>
            <div className="input-group">
              <label className="form-label">Username</label>
              <input
                type="text"
                placeholder="Masukkan Nama Anda"
                className="login-input"
                value={name}
                onChange={(e) => setName(e.target.value)}
              />
              {nameError && <div className="error-message">{nameError}</div>}
            </div>

            <div className="input-group">
              <label className="form-label">Password</label>
              <input
                type={showPassword ? "text" : "password"}
                placeholder="Masukkan Kata Sandi Anda"
                className="login-input"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
              />
              <FontAwesomeIcon
                icon={showPassword ? faEyeSlash : faEye}
                className="eye-icon"
                onClick={() => setShowPassword(!showPassword)}
              />
              {passwordError && <div className="error-message">{passwordError}</div>}
            </div>

            <button
              type="submit"
              className={`login-button ${!isFormValid || isLoading ? "disabled" : ""}`}
              disabled={!isFormValid || isLoading}
            >
              {isLoading ? (
                <>
                  <span className="spinner" />
                  <span>Loading...</span>
                </>
              ) : (
                "Masuk"
              )}
            </button>

            <div className="login-extra">
              <button type="button" className="login-forgot" onClick={onForgetPassword}>
                LUPA PASSWORD?
              </button>
            </div>
          </form>

          <div className="login-footer">
            <span>Belum punya akun? Silakan </span>
            <button type="button" className="register-link" onClick={onRegister}>
              Daftar
            </button>
          </div>
        </div>
      </div>
    </>
  );
};

export default LoginScreen;
