import React, { useEffect, useRef, useState } from "react";
import maplibregl from "maplibre-gl";
import "maplibre-gl/dist/maplibre-gl.css";
import "./GeometriScreen.css";

const MAP_SERVICE_KEY = "67b6a6056fb80e64559cc07e";
const INITIAL_COORDS = { lat: -2.5, lng: 118.5 }; // Tetap pakai objek

const GeometriScreen = ({ onSave, onBack }) => {
  const mapContainer = useRef(null);
  const mapRef = useRef(null);
  const markerRef = useRef(null);

  const [coords, setCoords] = useState(INITIAL_COORDS); // Tetap pakai objek {lat, lng}
  const [loading, setLoading] = useState(false);
  const [statusMsg, setStatusMsg] = useState("");

  useEffect(() => {
    if (mapRef.current) return;

    mapRef.current = new maplibregl.Map({
      container: mapContainer.current,
      style: `https://basemap.mapid.io/styles/basic/style.json?key=${MAP_SERVICE_KEY}`,
      center: [INITIAL_COORDS.lng, INITIAL_COORDS.lat],
      zoom: 5,
    });

    markerRef.current = new maplibregl.Marker({ draggable: true })
      .setLngLat([INITIAL_COORDS.lng, INITIAL_COORDS.lat])
      .addTo(mapRef.current);

    markerRef.current.on("dragend", () => {
      const { lat, lng } = markerRef.current.getLngLat();
      setCoords({ lat, lng });
      setStatusMsg("Koordinat diubah secara manual.");
    });
  }, []);

  const handleActivateLocation = () => {
    if (!navigator.geolocation) {
      alert("Geolocation tidak didukung oleh browser.");
      return;
    }

    setLoading(true);
    setStatusMsg("Mendeteksi lokasi...");

    navigator.geolocation.getCurrentPosition(
      (position) => {
        const { latitude, longitude } = position.coords;
        setCoords({ lat: latitude, lng: longitude });
        setStatusMsg("Lokasi berhasil ditemukan!");
        setLoading(false);

        if (mapRef.current && markerRef.current) {
          markerRef.current.setLngLat([longitude, latitude]);
          mapRef.current.flyTo({ center: [longitude, latitude], zoom: 15 });
        }
      },
      (error) => {
        console.error("Gagal mendapatkan lokasi:", error);
        setStatusMsg("Gagal mendeteksi lokasi: " + error.message);
        setLoading(false);
      },
      {
        enableHighAccuracy: true,
        timeout: 10000,
        maximumAge: 0,
      }
    );
  };

  const handleLanjut = () => {
    if (onSave) {
      onSave([coords.lng, coords.lat]); // Kirim dalam format [longitude, latitude]
    }
  };

  return (
    <div className="geo-container">
      <div className="geo-card">
        <div className="geo-header">
          <button onClick={onBack} className="geo-back-button">
            <img src="/kembali.png" alt="Kembali" />
          </button>
        </div>

        <div className="geo-logo-container">
          <img src="/HKN.png" alt="HKN Logo" className="geo-logo" />
        </div>

        <div className="geo-section">
          <button
            onClick={handleActivateLocation}
            className="geo-button"
            disabled={loading}
          >
            {loading ? "Mendeteksi Lokasi..." : "Aktifkan Lokasi"}
          </button>

          <input
            type="text"
            value={coords.lat}
            readOnly
            placeholder="Latitude"
            className="geo-input"
          />
          <input
            type="text"
            value={coords.lng}
            readOnly
            placeholder="Longitude"
            className="geo-input"
          />

          {statusMsg && <p className="geo-status">{statusMsg}</p>}
        </div>

        <div ref={mapContainer} className="geo-map" />

        <div className="geo-section">
          <button onClick={handleLanjut} className="geo-button-lanjut">
            Lanjut
          </button>
        </div>
      </div>
    </div>
  );
};

export default GeometriScreen;
