import React, { useState } from "react";
import "./ForgetPasswordScreen3.css";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faEye, faEyeSlash } from "@fortawesome/free-solid-svg-icons";
import axios from "axios";

const ForgetPasswordScreen3 = ({ data, onDone, onBack }) => {
  const [password1, setPassword1] = useState("");
  const [password2, setPassword2] = useState("");
  const [errorMatch, setErrorMatch] = useState("");
  const [errorFormat, setErrorFormat] = useState("");
  const [success, setSuccess] = useState("");
  const [showPassword1, setShowPassword1] = useState(false);
  const [showPassword2, setShowPassword2] = useState(false);

  const passwordRegex = /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[\W_]).{8,}$/;

  const handleSubmit = async (e) => {
    e.preventDefault();
    setErrorMatch("");
    setErrorFormat("");
    setSuccess("");

    const isPasswordMatch = password1 === password2;
    const isPasswordValid = passwordRegex.test(password1);

    if (!password1 || !password2) {
      setErrorMatch("Semua kolom wajib diisi.");
      return;
    }

    // Tampilkan error password tidak cocok terlebih dahulu jika dua-duanya salah
    if (!isPasswordMatch) {
      setErrorMatch("Password tidak cocok. Masukkan kembali password.");
    }

    if (!isPasswordValid) {
      setErrorFormat(
        "Password harus minimal 8 karakter, mengandung huruf besar, huruf kecil, angka, dan simbol."
      );
    }

    if (!isPasswordMatch || !isPasswordValid) return;
    console.log("Password yang anda rubah :", password1)
    console.log("username anda:", data.username)
    try {
      const response = await axios.post(
        "https://geoserver.mapid.io/mail/new_password",
        {
          username: data?.username || "",
          password1,
          password2,
        }
      );

      if (response.status === 200) {
        setSuccess("Password berhasil diubah.");
        setTimeout(() => {
          onDone();
        }, 2000);
      } else {
        setErrorMatch("Gagal mengubah password.");
      }
    } catch (err) {
      const msg = err.response?.data?.message || "Terjadi kesalahan saat mengirim.";
      setErrorMatch(msg);
    }
  };

  return (
    <div className="scroll-wrapper">
      <div className="register-container">
        <div className="register-header">
          <button onClick={onBack} className="back-button2">
            <img src="/kembali.png" alt="Kembali" />
          </button>
        </div>

        <div className="logo-container">
          <img src="/HKN.png" className="logo" id="HKN" alt="HKN" />
          <h2>Atur Ulang Password</h2>
        </div>
        <h3>Masukkan Password Baru Anda</h3>

        <form className="register-form" onSubmit={handleSubmit}>
          <label>Password Baru *</label>
          <div className="input-wrapper">
            <input
              type={showPassword1 ? "text" : "password"}
              className="register-input"
              placeholder="Masukkan Password Baru"
              value={password1}
              onChange={(e) => setPassword1(e.target.value)}
            />
            <FontAwesomeIcon
              icon={showPassword1 ? faEyeSlash : faEye}
              className="eye-icon3"
              onClick={() => setShowPassword1(!showPassword1)}
            />
          </div>

          {/* Error format muncul di bawah input password baru */}
          {errorFormat && (
            <div style={{ color: "red", fontSize: "12px", marginTop: "4px" }}>
              {errorFormat}
            </div>
          )}

          <label>Konfirmasi Password *</label>
          <div className="input-wrapper">
            <input
              type={showPassword2 ? "text" : "password"}
              className="register-input"
              placeholder="Konfirmasi Password Baru"
              value={password2}
              onChange={(e) => setPassword2(e.target.value)}
            />
            <FontAwesomeIcon
              icon={showPassword2 ? faEyeSlash : faEye}
              className="eye-icon3"
              onClick={() => setShowPassword2(!showPassword2)}
            />
          </div>

          {/* Error match muncul di bawah input konfirmasi */}
          {errorMatch && (
            <div style={{ color: "red", fontSize: "12px", marginTop: "4px" }}>
              {errorMatch}
            </div>
          )}

          {success && (
            <div style={{ color: "green", fontSize: "12px", marginTop: "6px" }}>
              {success}
            </div>
          )}

          <button
            type="submit"
            className="register-button"
            style={{
              backgroundColor: password1 && password2 ? "#FFB532" : undefined,
              color: password1 && password2 ? "#292B32" : undefined,
            }}
            disabled={!password1 || !password2}
          >
            Simpan Password
          </button>
        </form>
      </div>
    </div>
  );
};

export default ForgetPasswordScreen3;
