import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import AlumniMap from './AlumniMap';
import './DetailKegiatan.css';

const DetailKegiatan = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch('https://geoserver.mapid.io/layers_new/get_layer?api_key=933cb5f2fe89479b8b692a1f8f406639&layer_id=6837ebe8c0529a72940f17a4&project_id=67fddd3d7df91cc4425c7fba')
      .then(res => res.json())
      .then((geojson) => {
        const found = geojson.features.find(f => f.id === id);
        if (!found) return setData(null);

        const props = found.properties || {};
        setData({
            id: found.id,
            judul: props["Nama Kegiatan"],
            deskripsi: props["Deskripsi"],
            tanggal: props["Tanggal"],
            jam: props["Jam"],
            gambar: props["Poster Kegiatan"],
            lat: found.geometry?.coordinates?.[1],
            lng: found.geometry?.coordinates?.[0],
            galeri: [
              props["Foto tambahan 1"],
              props["Foto tambahan 2"],
              props["Foto tambahan 3"]
            ].filter(Boolean),
            linkPendaftaran: props["Link Pendaftaran"],
            linkLokasi: props["Link Lokasi"],
            selesai: new Date(props["Tanggal"]) < new Date()
          });
      })
      .catch(console.error)
      .finally(() => setLoading(false));
  }, [id]);

  function getCalendarDateRange(dateStr) {
    const date = new Date(dateStr);
    const start = date.toISOString().replace(/-|:|\.\d\d\d/g, "").slice(0, 15) + "00Z";
    const endDate = new Date(date.getTime() + 60 * 60 * 1000);
    const end = endDate.toISOString().replace(/-|:|\.\d\d\d/g, "").slice(0, 15) + "00Z";
    return `${start}/${end}`;
  }

    function handleDownload(url) {
      const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);

      if (isMobile) {
        // Mobile: langsung buka link di tab baru
        window.open(url, '_blank');
        showPopup("✅ Unduh Gambar Berhasil");
      } else {
        // Desktop: aman pakai fetch & blob
        fetch(url)
          .then(res => res.blob())
          .then(blob => {
            const link = document.createElement('a');
            link.href = window.URL.createObjectURL(blob);
            link.download = url.split('/').pop();
            link.click();
            showPopup("✅ Unduh Gambar Berhasil");
          })
          .catch(() => showPopup("❌ Gagal mengunduh foto"));
      }
    }

  function showPopup(message) {
    const popup = document.createElement('div');
    popup.innerText = message;

    popup.style.position = 'fixed';
    popup.style.top = '-100px';
    popup.style.left = '0';
    popup.style.right = '0';
    popup.style.margin = '0 auto';
    popup.style.width = 'calc(80% - 32px)'; // biar ada jarak kanan kiri
    popup.style.maxWidth = '500px';
    popup.style.background = '#38cb82'; // hijau sukses
    popup.style.color = '#fff';
    popup.style.padding = '14px 20px';
    popup.style.borderRadius = '8px';
    popup.style.zIndex = 9999;
    popup.style.fontSize = '0.95rem';
    popup.style.fontWeight = '600';
    popup.style.boxShadow = '0 2px 10px rgba(0,0,0,0.25)';
    popup.style.transition = 'top 0.4s ease';

    document.body.appendChild(popup);

    setTimeout(() => (popup.style.top = '20px'), 50); // slide turun
    setTimeout(() => {
      popup.style.top = '-100px';
      setTimeout(() => popup.remove(), 300);
    }, 2500);
  }

  if (loading) return <p style={{ textAlign: 'center' }}>Loading...</p>;
  if (!data) return <p style={{ textAlign: 'center' }}>Data tidak ditemukan.</p>;

  return (
    <div className="detail-container">
      {/* HEADER */}
      <div className="detail-header">
        <button className="back-btn" onClick={() => navigate('/home')}>‹</button>
        <h3 className="header-title">Detail Kegiatan</h3>
        <div style={{ width: 24 }} />
      </div>

      {/* MAIN EVENT IMAGE */}
      <div className="main-event-image">
        <img
          src={data.gambar || 'https://via.placeholder.com/800x400?text=No+Image'}
          alt={data.judul}
        />
        <span className="event-date">
          {new Date(data.tanggal).toLocaleDateString('id-ID', {
            day: '2-digit',
            month: 'long',
            year: 'numeric'
          })}
        </span>
      </div>

            {/* INFO */}
      <div className="event-info">
        <h4>{data.judul}</h4>
        <p>{data.deskripsi}</p>

        <button
          className="calendar-btn"
          onClick={() => {
            const calendarUrl = `https://calendar.google.com/calendar/render?action=TEMPLATE&text=${encodeURIComponent(data.judul)}&dates=${getCalendarDateRange(data.tanggal)}&details=${encodeURIComponent(data.deskripsi)}`;
            window.open(calendarUrl, '_blank');
          }}
        >
          Tambahkan ke Kalender
        </button>

        {/* ✅ Tombol Daftar */}
        {data.linkPendaftaran && (
          <button
            className="calendar-btn"
            onClick={() => window.open(data.linkPendaftaran, '_blank')}
          >
            Daftar Sekarang
          </button>
        )}

        {/* ✅ Tombol Link Lokasi */}
        {data.linkLokasi && (
          <button
            className="calendar-btn"
            onClick={() => window.open(data.linkLokasi, '_blank')}
          >
            Lihat Lokasi
          </button>
        )}
      </div>
      
      {/* Peta Lokasi */}
      {data.lat && data.lng && (
        <div style={{ marginTop: '1.5rem' }}>
          <h4 style={{ marginBottom: '0.5rem' }}>Lokasi</h4>
          <AlumniMap
            data={[
              {
                lat: data.lat,
                lng: data.lng,
                nama: data.judul,
                kota: '',
                pekerjaan: ''
              }
            ]}
          />
        </div>
      )}

      {/* GALERI */}
      <div className="gallery-section">
        <h4>Galeri Foto Lainnya</h4>
        {data.galeri.map((url, i) => (
          <div key={i} className="gallery-card">
            <div className="gallery-image-wrapper">
              <img src={url} alt={`Galeri ${i + 1}`} />
              <button
                className="floating-download"
                onClick={() => handleDownload(url)}
                title="Unduh Foto"
              >
                ⬇
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default DetailKegiatan;