import React, { useState, useEffect, useMemo } from "react";
import axios from "axios";
import "./DataLengkapScreen5.css";

const DataLengkapScreen5 = ({
  onBack,
  onSuccess,
  goToSection,
  formDataAll,
  setFormDataAll,
  coords,
}) => {
  const [formData, setFormData] = useState({});

  const fields = useMemo(() => [
    {
      label: "Minat dan Kontribusi",
      name: "6e0a4fed-4131-44d5-b7ff-f489087a6061",
      type: "datalist",
      options: ["Networking", "Donasi"],
      placeholder: "Contoh: Lingkungan, Pendidikan, dll.",
    },
    {
      label: "Link Sosial Media",
      name: "bd45ee2b-adce-4165-aed6-d45db44fb818",
      type: "text",
      placeholder: "Masukkan tautan profil sosial media",
    },
    {
      label: "Foto Diri (opsional)",
      name: "658b0f25-1f76-4219-bf8b-fafecefa87bd",
      type: "file",
    },
    {
      label: "Cerita Kenangan Menarik di Krida (opsional)",
      name: "97e0bf48-4a30-40c6-83ec-6e768d622ea0",
      type: "textarea",
      placeholder: "Ceritakan pengalaman berkesanmu di Krida",
    },
    {
      label: "NIS",
      name: "6f029f2e-5744-4d4d-82b4-77441b3c1fb3",
      type: "text",
      placeholder: "Masukkan Nomor Induk Siswa",
    },
  ], []);

  useEffect(() => {
    const initial = {};
    fields.forEach((field) => {
      initial[field.name] = formDataAll?.feature?.properties?.[field.name] || "";
    });
    setFormData(initial);
  }, [fields, formDataAll?.feature?.properties]);

  const handleChange = (e) => {
    const { name, value, files } = e.target;
    const newValue = files ? files[0] : value;
    setFormData((prev) => ({ ...prev, [name]: newValue }));
  };

  const handleSubmit = async () => {
  console.log("📍 Koordinat sebelum submit:", coords);
  const full_name = localStorage.getItem("full_name") || "";
  const name = localStorage.getItem("username") || "";
  const phone_number = localStorage.getItem("phone_number") || "";

  const accessToken = localStorage.getItem("accessTokenAPI");
  let fotoUrl = "";

  // ✅ Upload Foto jika ada
  const fotoField = formData["658b0f25-1f76-4219-bf8b-fafecefa87bd"];
  if (fotoField instanceof File) {
    const formUpload = new FormData();
    formUpload.append("file", fotoField);
    formUpload.append("type", "general_image");

    try {
      const uploadRes = await axios.post(
        "https://geoserver.mapid.io/upload",
        formUpload,
        {
          headers: {
            accesstoken: accessToken,
            "Content-Type": "multipart/form-data",
          },
        }
      );
      fotoUrl = uploadRes.data?.data?.Location || "";
      console.log("✅ Upload Foto URL:", fotoUrl);
    } catch (error) {
      console.error("❌ Gagal upload foto:", error);
      alert("Gagal upload foto. Coba lagi.");
      return;
    }
  }

  const finalProperties = {
    ...(formDataAll?.feature?.properties || {}),
    ...formData,
    "658b0f25-1f76-4219-bf8b-fafecefa87bd": fotoUrl, // ✅ Simpan URL hasil upload
    "b248e4a2-d648-44e1-9ef4-7401539c0ab0": full_name,
    "257cab30-92f4-4ba9-a44f-3fee07656b6c": name,
    "599ee1ae-0fe8-498c-aa19-ccf3d72e4683": phone_number,
  };

  const [lng, lat] = Array.isArray(coords) ? coords : [0, 0];

  const payload = {
    geo_layer_id: "6804f7733996df0058de7279",
    link: "hkn",
    feature: {
      type: "Feature",
      geometry: {
        type: "Point",
        coordinates: [lng, lat],
      },
      properties: finalProperties,
    },
  };

  console.log("📦 Payload Final:", payload);

  try {
    await axios.post("https://geoserver.mapid.io/forms/push_feature", payload, {
      headers: {
        accesstoken: accessToken,
      },
    });
    localStorage.setItem("DataLengkap", JSON.stringify(payload));
    onSuccess();
  } catch (error) {
    console.error("❌ Gagal kirim data:", error.response || error);
    alert("Gagal mengirim data. Silakan coba lagi.");
  }
};


  return (
    <div className="dl5-container">
      <div className="dl5-header">
        <button onClick={onBack} className="dl5-back-button">
          <img src="/kembali.png" alt="Kembali" />
        </button>
      </div>

      <div className="dl5-section-buttons">
        {[1, 2, 3, 4, 5].map((num) => (
          <button
            key={num}
            onClick={() => goToSection(num)}
            className={`dl5-circle-button ${num === 5 ? "active" : ""}`}
          >
            {num}
          </button>
        ))}
      </div>

      <div className="dl5-section-title">
        <h2>Data Tambahan</h2>
        <span className="dl5-section-subtitle">Section 5/5</span>
      </div>

      <div className="dl5-form-section">
        {fields.map((field) => (
          <div key={field.name} className="dl5-input-box">
            <label className="dl5-input-label">{field.label}</label>
            {field.name !== "658b0f25-1f76-4219-bf8b-fafecefa87bd" && (
              <p className="dl5-required-text">Wajib diisi</p>
            )}
            {field.type === "datalist" ? (
              <>
                <input
                  type="text"
                  name={field.name}
                  list={`list-${field.name}`}
                  value={formData[field.name]}
                  onChange={handleChange}
                  className="dl5-form-input"
                  placeholder={field.placeholder}
                />
                <datalist id={`list-${field.name}`}>
                  {field.options.map((option) => (
                    <option key={option} value={option} />
                  ))}
                </datalist>
              </>
            ) : field.type === "textarea" ? (
              <textarea
                name={field.name}
                value={formData[field.name]}
                onChange={handleChange}
                className="dl5-form-input"
                placeholder={field.placeholder}
                rows={4}
              />
            ) : field.type === "file" ? (
              <input
                type="file"
                name={field.name}
                accept="image/*"
                onChange={handleChange}
                className="dl5-form-input"
              />
            ) : (
              <input
                type="text"
                name={field.name}
                value={formData[field.name]}
                onChange={handleChange}
                className="dl5-form-input"
                placeholder={field.placeholder}
              />
            )}
          </div>
        ))}
      </div>

      <div className="dl5-form-footer">
        <button className="dl5-submit-button" onClick={handleSubmit}>
          Submit
        </button>
      </div>
    </div>
  );
};

export default DataLengkapScreen5;
