import React, { useEffect, useMemo, useState } from "react";
import "./DataLengkapScreen4.css";

const DataLengkapScreen4 = ({
  onNext,
  onBack,
  goToSection,
  formDataAll,
  setFormDataAll,
}) => {
  const [formData, setFormData] = useState({});

  const fields = useMemo(() => [
    {
      label: "Profesi / Jabatan",
      name: "ae6eefea-caf6-4750-97cf-db4afb890235",
      type: "datalist",
      options: ["Pelajar/Mahasiswa", "Dosen"],
      placeholder: "Contoh: Pelajar/Mahasiswa",
    },
    {
      label: "Instansi / Perusahaan",
      name: "c7193f90-f88f-420d-ad69-a1936ce86881",
      type: "datalist",
      options: ["Pemerintah Pusat", "Pemerintah Provinsi"],
      placeholder: "Contoh: Pemerintah Pusat",
    },
    {
      label: "Bidang / Industri",
      name: "ddc6cd90-6be8-4ddd-ba9f-d45ae265eb77",
      type: "datalist",
      options: ["Pemerintahan", "Militer / Kepolisian"],
      placeholder: "Contoh: Pemerintahan",
    },
    {
      label: "Kota/Kabupaten Tempat Bekerja",
      name: "7248ec10-1352-4080-a707-dfc9fa2d2325",
      type: "datalist",
      options: ["Jakarta Pusat", "Jakarta Barat"],
      placeholder: "Contoh: Jakarta Pusat",
    },
    {
      label: "Apakah bersedia terlibat kegiatan HKN?",
      name: "be92ce14-e5f6-403e-9696-596a8b570d35",
      type: "select",
      options: ["Ya", "Tidak"],
    },
  ], []);

  useEffect(() => {
    const initialData = {};
    fields.forEach((field) => {
      initialData[field.name] = formDataAll?.feature?.properties?.[field.name] || "";
    });
    setFormData(initialData);
  }, [fields, formDataAll?.feature?.properties]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleNext = () => {
    const updatedAll = {
      ...formDataAll,
      feature: {
        ...formDataAll.feature,
        type: "Feature",
        geometry: formDataAll?.feature?.geometry || null,
        properties: {
          ...(formDataAll?.feature?.properties || {}),
          ...formData,
        },
      },
    };

    console.log("✅ Data Section 4:", updatedAll);
    setFormDataAll(updatedAll);
    onNext();
  };

  return (
    <div className="dl4-container">
      <div className="dl4-header">
        <button onClick={onBack} className="dl4-back-button">
          <img src="/kembali.png" alt="Kembali" />
        </button>
      </div>

      <div className="dl4-section-buttons">
        {[1, 2, 3, 4, 5].map((num) => (
          <button
            key={num}
            onClick={() => goToSection(num)}
            className={`dl4-circle-button ${num === 4 ? "active" : ""}`}
          >
            {num}
          </button>
        ))}
      </div>

      <div className="dl4-section-title">
        <h2>Data Pekerjaan</h2>
        <span className="dl4-section-subtitle">Section 4/5</span>
      </div>

      <div className="dl4-form-section">
        {fields.map((field) => (
          <div key={field.name} className="dl4-input-box">
            <label className="dl4-input-label">{field.label}</label>
            <p className="dl4-required-text">Wajib diisi</p>
            {field.type === "select" ? (
              <select
                name={field.name}
                value={formData[field.name]}
                onChange={handleChange}
                className="dl4-form-input"
              >
                <option value="">Pilih</option>
                {field.options.map((option) => (
                  <option key={option} value={option}>
                    {option}
                  </option>
                ))}
              </select>
            ) : field.type === "datalist" ? (
              <>
                <input
                  type="text"
                  name={field.name}
                  list={`list-${field.name}`}
                  value={formData[field.name]}
                  onChange={handleChange}
                  className="dl4-form-input"
                  placeholder={field.placeholder}
                />
                <datalist id={`list-${field.name}`}>
                  {field.options.map((option) => (
                    <option key={option} value={option} />
                  ))}
                </datalist>
              </>
            ) : (
              <input
                type="text"
                name={field.name}
                value={formData[field.name]}
                onChange={handleChange}
                className="dl4-form-input"
                placeholder={`Tulis ${field.label.toLowerCase()} di sini`}
              />
            )}
          </div>
        ))}
      </div>

      <div className="dl4-form-footer">
        <button className="dl4-next-button" onClick={handleNext}>
          Next page
        </button>
      </div>
    </div>
  );
};

export default DataLengkapScreen4;
