import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { FaInstagram, FaLinkedin } from 'react-icons/fa';
import AlumniMap from './AlumniMap';
import { FaGlobe } from 'react-icons/fa';

const ProfileAlumni = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [alumni, setAlumni] = useState(null);

useEffect(() => {
  const accessToken = 'eyJhbGciOiJIUzI1NiJ9.eyJ1c2VyX2lkIjoiNjdhZjExMTYwZWNjNTEyNTgyMTI1ZjM2IiwidXNlcm5hbWUiOiJsb2thdmF0YV9ndXN0aWF5dW1hZGUifQ.uSPJW2ItArtNGO4E-Rp-Bl8P1miyxlTY8SG4YHmcGG4';
  const layerId = '6804f7733996df0058de7279';
  const projectId = '67fddd3d7df91cc4425c7fba';

  fetch(`https://geoserver.mapid.io/moneys_bun/v2/get_layer_detail_by_id/${layerId}/${projectId}?skip=0&limit=1000`, {
    method: 'GET',
    headers: {
      'accept': '*/*',
      'accesstoken': accessToken
    }
  })
    .then(res => res.json())
    .then(data => {
      if (!Array.isArray(data)) return;

      const found = data.find((item) => item._id === id);
      if (!found) return;

      const props = found.properties || {};

      setAlumni({
        id: found._id,
        nama: props["b248e4a2-d648-44e1-9ef4-7401539c0ab0"] || "Tanpa Nama",
        kota: props["7248ec10-1352-4080-a707-dfc9fa2d2325"] || "-",
        pekerjaan: props["ddc6cd90-6be8-4ddd-ba9f-d45ae265eb77"] || "-",
        tanggal_lahir: props["e7b93943-5c4c-4d3e-a781-8b3c679bc920"] || null,
        sosialMediaLink: props["bd45ee2b-adce-4165-aed6-d45db44fb818"] || null,
        foto: props["658b0f25-1f76-4219-bf8b-fafecefa87bd"] || "",
        lat: found.geometry?.coordinates?.[1],
        lng: found.geometry?.coordinates?.[0]
      });
    });
}, [id]);


  if (!alumni) return <p style={{ textAlign: 'center' }}>Memuat data alumni...</p>;

  return (
    <div style={{ padding: '1rem', fontFamily: 'sans-serif', maxWidth: 500, margin: '0 auto' }}>
      
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', marginBottom: '1rem', position: 'relative' }}>
        <button
          onClick={() => navigate('/dashboard')}
          style={{
            position: 'absolute',
            left: 0,
            fontSize: '2rem',
            border: 'none',
            background: 'none',
            cursor: 'pointer',
            padding: '0 8px',
            lineHeight: 1
          }}
        >
          ‹
        </button>
        <h2 style={{ margin: 0, textAlign: 'center' }}>Profil Alumni</h2>
      </div>

      <hr style={{ margin: '1rem 0' }} />

      {/* Biodata dan Foto */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
        <img
          src={alumni.foto || '/no-profile.jpg'}
          alt={alumni.nama}
          style={{
            width: 150,
            height: 150,
            objectFit: 'cover',
            borderRadius: '8px'
          }}
        />
        <div>
          <h3 style={{ margin: 0 }}>{alumni.nama}</h3>

          {/* Informasi rata kiri */}
          <div style={{ display: 'flex', flexDirection: 'column', gap: '4px', marginTop: 8 }}>
            <div style={{ display: 'flex', gap: 8 }}>
              <span style={{ width: 24 }}>🎂</span>
              <span>
                {alumni.tanggal_lahir
                  ? new Date(alumni.tanggal_lahir).toLocaleDateString('id-ID', {
                      day: '2-digit',
                      month: 'long',
                      year: 'numeric'
                    })
                  : 'Tanggal tidak tersedia'}
              </span>
            </div>
            <div style={{ display: 'flex', gap: 8 }}>
              <span style={{ width: 24 }}>💼</span>
              <span>{alumni.pekerjaan}</span>
            </div>
            <div style={{ display: 'flex', gap: 8 }}>
              <span style={{ width: 24 }}>📍</span>
              <span>{alumni.kota}</span>
            </div>
          </div>

          {/* Sosial Media */}
<div style={{ marginTop: 10, display: 'flex', alignItems: 'center', gap: 8 }}>
  <span>Social Media:</span>
  {alumni.sosialMediaLink ? (
    <a
      href={alumni.sosialMediaLink}
      target="_blank"
      rel="noopener noreferrer"
      title="Social Media"
      style={{ display: 'flex', alignItems: 'center', color: 'inherit' }}
    >
      {alumni.sosialMediaLink.includes('instagram') ? (
        <FaInstagram size={20} />
      ) : alumni.sosialMediaLink.includes('linkedin') ? (
        <FaLinkedin size={20} />
      ) : (
        <FaGlobe size={20} />
      )}
    </a>
  ) : (
    <span style={{ color: '#ccc' }}>Tidak tersedia</span>
  )}
</div>
        </div>
      </div>

      <hr style={{ margin: '2rem 0' }} />

      {/* Peta Lokasi */}
      <div>
        <h4 style={{ marginBottom: '0.5rem' }}>Lokasi</h4>
        <AlumniMap data={[alumni]} />
      </div>
    </div>
  );
};

export default ProfileAlumni;