import React, { useEffect, useState, useRef } from "react";
import "./ProfileScreen.css";
import { FaChevronRight, FaUser} from "react-icons/fa";
import { IoCallOutline } from "react-icons/io5";
import { MdLockOutline } from "react-icons/md";
import { HomeIcon, Users, MessageCircle, User } from "lucide-react";
import { useNavigate } from "react-router-dom";
// import html2canvas from "html2canvas"; // pastikan sudah install: npm install html2canvas

const ProfileScreen = ({ onChange, onData }) => {
  const [userData, setUserData] = useState(null);
  const navigate = useNavigate();
  const idCardRef = useRef(null);

  useEffect(() => {
    const storedUser = localStorage.getItem("user");
    if (!storedUser) return;

    const { name } = JSON.parse(storedUser);
    const layerId = '6804f7733996df0058de7279';
    const projectId = '67fddd3d7df91cc4425c7fba';

    fetch(`https://geoserver.mapid.io/moneys_bun/v2/get_layer_detail_by_id/${layerId}/${projectId}?skip=0&limit=1000000000`)
      .then(res => res.json())
      .then(data => {
        const found = data.find(item =>
          item.properties?.["257cab30-92f4-4ba9-a44f-3fee07656b6c"] === name
        );

        if (found) {
          setUserData({
            nama: found.properties["b248e4a2-d648-44e1-9ef4-7401539c0ab0"],
            kota: found.properties["7248ec10-1352-4080-a707-dfc9fa2d2325"],
            foto: found.properties["658b0f25-1f76-4219-bf8b-fafecefa87bd"]
          });
        }
      })
      .catch(console.error);
  }, []);

const handleLogout = () => {
  localStorage.removeItem("jwt");
  localStorage.removeItem("user");
  localStorage.removeItem("feature_key");
  navigate("/");
};

  // const handleDownload = () => {
  //   if (!idCardRef.current) return;

  //   html2canvas(idCardRef.current).then(canvas => {
  //     const link = document.createElement("a");
  //     link.download = `idcard_${userData?.nama || "alumni"}.jpg`;
  //     link.href = canvas.toDataURL("image/jpeg");
  //     link.click();
  //   });
  // };

  return (
    <div className="profile-wrapper">
      {/* Header */}
      <div className="box box-header">
        <h2>Profil</h2>
      </div>

      {/* Foto & Info */}
      <div className="box box-profile">
        <div className="profile-img-wrapper">
          {userData?.foto ? (
            <img src={userData.foto} alt="Foto Profil" className="profile-img" />
          ) : (
            <div className="default-icon-wrapper">
              <FaUser className="default-icon" />
            </div>
          )}
        </div>
        <div className="profile-info">
          <h3>{userData?.nama || "Memuat..."}</h3>
          <p>{userData?.kota || ""}</p>
          <p>{/* Email dihapus sesuai permintaan */}</p>
        </div>
      </div>

      {/* ID Card */}
      <div className="box box-idcard" ref={idCardRef}>
        <div className="box-kartu">
          <div className="idcard-logo">
            <img src="/HKN.png" alt="HKN Logo" />
            <div className="idcard-text">
              <h4>{userData?.nama || "Nama Alumni"}</h4>
              <p>{userData?.kota || "Asal Kota"}</p>
            </div>
          </div>
          <div className="idcard-photo">
            {userData?.foto ? (
              <img src={userData.foto} alt="Foto ID" />
            ) : (
              <div className="default-id-icon-wrapper">
                <FaUser className="default-id-icon" />
              </div>
            )}
          </div>
        </div>
      </div>
{/* 
      <button className="download-button" onClick={handleDownload}>
        <FaDownload style={{ marginRight: "5px" }} />
        Unduh ID Card
      </button> */}

      {/* Akun */}
      <div className="box box-akun">
        <h4>Akun</h4>
        <div className="nav-item">
          <FaUser className="nav-icon" />
          <button className="nav-button" onClick={onData}>
            Ubah Data Diri
          </button>
          <FaChevronRight className="chevron-icon" />
        </div>
        <div className="nav-item">
          <MdLockOutline className="nav-icon" />
          <button className="nav-button" onClick={onChange}>
            Ubah Password
          </button>
          <FaChevronRight className="chevron-icon" />
        </div>
      </div>

      {/* Info lainnya */}
      <div className="box box-info">
        <h4>Info Lainnya</h4>
        <div className="nav-item">
          <IoCallOutline className="nav-icon" />
          <button className="nav-button" onClick={() => console.log("Navigasi ke Call Center")}>
            Call Center
          </button>
          <FaChevronRight className="chevron-icon" />
        </div>
      </div>

      <div style={{ height: '100px'}}>
         <button className="logout-button" onClick={handleLogout}>Keluar</button>
      {/* Bottom nav */}
      <div className="bottom-nav">
        <button className="nav-btn" onClick={() => navigate('/home')}>
          <HomeIcon size={22} />
          <span className="nav-label">Beranda</span>
        </button>
        <button className="nav-btn" onClick={() => navigate('/dashboard')}>
          <Users size={22} />
          <span className="nav-label">Alumni</span>
        </button>
        <button className="nav-btn" onClick={() => navigate('/chat')}>
          <MessageCircle size={22} />
          <span className="nav-label">Chat</span>
        </button>
        <button className="nav-btn active">
          <User size={22} />
          <span className="nav-label">Profil</span>
        </button>
      </div>
    </div>
  </div>
  );
};

export default ProfileScreen;
