import React, { useEffect, useMemo, useState } from "react";
import "./DataLengkapScreen3.css";

const DataLengkapScreen3 = ({
  onNext,
  onBack,
  goToSection,
  formDataAll,
  setFormDataAll,
}) => {
  const [formData, setFormData] = useState({});

  const fields = useMemo(() => [
    {
      label: "Universitas / Sekolah Lanjutan",
      name: "f83df530-9b7c-4a45-ad7c-2678b024612e",
      type: "datalist",
      options: ["Universitas Indonesia (UI)", "Institut Teknologi Bandung (ITB)"],
    },
    {
      label: "Jurusan",
      name: "5e5eb224-a5a0-45b9-aa99-8190c97eb454",
      type: "datalist",
      options: ["Teknik Sipil", "Teknik Arsitektur"],
    },
    {
      label: "Gelar",
      name: "def0c6cd-fa51-4b85-a627-5951c47b225c",
      type: "datalist",
      options: ["A.P.", "A.Ma."],
    },
  ], []);

  useEffect(() => {
    const initialData = {};
    fields.forEach((field) => {
      initialData[field.name] = formDataAll?.feature?.properties?.[field.name] || "";
    });
    setFormData(initialData);
  }, [fields, formDataAll?.feature?.properties]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleNext = () => {
    const updatedAll = {
      ...formDataAll,
      feature: {
        ...formDataAll.feature,
        type: "Feature",
        geometry: formDataAll?.feature?.geometry || null,
        properties: {
          ...(formDataAll?.feature?.properties || {}),
          ...formData,
        },
      },
    };

    console.log("✅ Data Section 3:", updatedAll.feature.properties);
    setFormDataAll(updatedAll);
    onNext();
  };

  return (
    <div className="dl3-container">
      <div className="dl3-header">
        <button onClick={onBack} className="dl3-back-button">
          <img src="/kembali.png" alt="Kembali" />
        </button>
      </div>

      <div className="dl3-section-buttons">
        {[1, 2, 3, 4, 5].map((num) => (
          <button
            key={num}
            onClick={() => goToSection(num)}
            className={`dl3-circle-button ${num === 3 ? "active" : ""}`}
          >
            {num}
          </button>
        ))}
      </div>

      <div className="dl3-section-title">
        <h2>Data Pendidikan</h2>
        <span className="dl3-section-subtitle">Section 3/5</span>
      </div>

      <div className="dl3-form-section">
        {fields.map((field) => (
          <div key={field.name} className="dl3-input-box">
            <label className="dl3-input-label">{field.label}</label>
            <p className="dl3-required-text">Wajib diisi</p>
            <input
              type="text"
              list={`list-${field.name}`}
              name={field.name}
              value={formData[field.name]}
              onChange={handleChange}
              className="dl3-form-input"
              placeholder={`Tulis ${field.label.toLowerCase()} di sini`}
            />
            <datalist id={`list-${field.name}`}>
              {field.options.map((option) => (
                <option key={option} value={option} />
              ))}
            </datalist>
          </div>
        ))}
      </div>

      <div className="dl3-form-footer">
        <button className="dl3-next-button" onClick={handleNext}>
          Next page
        </button>
      </div>
    </div>
  );
};

export default DataLengkapScreen3;
