import React, { useState, useEffect } from 'react';
import AlumniMap from './AlumniMap';
import './ChatAnimation.css';
import { useNavigate } from 'react-router-dom';
import AiAvatar from './AI.png';

const Chatbox = ({ onClose }) => {
  const navigate = useNavigate();

  const [messages, setMessages] = useState([
    { from: 'ai', text: 'Hai! Tanyakan tentang alumni kami.' }
  ]);
  const [input, setInput] = useState('');
  const [mapData, setMapData] = useState([]);
  const [showMap, setShowMap] = useState(false);
  const [semuaAlumni, setSemuaAlumni] = useState([]);
  const [filter, setFilter] = useState({ kota: '', pekerjaan: '' });
  const [expandedIndexes, setExpandedIndexes] = useState([]);

  useEffect(() => {
    const accessToken = 'eyJhbGciOiJIUzI1NiJ9.eyJ1c2VyX2lkIjoiNjdhZjExMTYwZWNjNTEyNTgyMTI1ZjM2IiwidXNlcm5hbWUiOiJsb2thdmF0YV9ndXN0aWF5dW1hZGUifQ.uSPJW2ItArtNGO4E-Rp-Bl8P1miyxlTY8SG4YHmcGG4'; // token kamu
    const layerId = '6804f7733996df0058de7279';
    const projectId = '67fddd3d7df91cc4425c7fba';

    fetch(`https://geoserver.mapid.io/moneys_bun/v2/get_layer_detail_by_id/${layerId}/${projectId}?skip=0&limit=1000`, {
      method: 'GET',
      headers: {
        'accept': '*/*',
        'accesstoken': accessToken
      }
    })
          .then(res => res.json())
          .then(data => {
          const enriched = data.map((item, i) => {
            const props = item.properties || {};
            const coords = item.geometry?.coordinates || [];

            return {
              id: item._id,
              nama: props["b248e4a2-d648-44e1-9ef4-7401539c0ab0"] || "Tanpa Nama",
              kota: props["7248ec10-1352-4080-a707-dfc9fa2d2325"] || "-",
              pekerjaan: props["ddc6cd90-6be8-4ddd-ba9f-d45ae265eb77"] || "-",
              foto: item.user?.profile_picture?.url || null,
              lat: coords[1] ?? null,  // ambil latitude
              lng: coords[0] ?? null   // ambil longitude
            };
          });
        setSemuaAlumni(enriched);
      })
      .catch(err => console.error('❌ Gagal mengambil data alumni MAPID:', err));
  }, []);

  useEffect(() => {
    const clickHandler = (e) => {
      if (e.target.classList.contains('alumni-link')) {
        const nama = decodeURIComponent(e.target.getAttribute('data-id'));
        const alumni = semuaAlumni.find(a => a.nama === nama);
        if (alumni) {
          setMapData([alumni]);
          setShowMap(true);
          setMessages((prev) => [
            ...prev,
            {
              from: 'ai',
              text: `🧾 Detail Alumni:<br>Nama: <a href="/alumni/${alumni.id}" target="_blank">${alumni.nama}</a><br>Kota: ${alumni.kota}<br>Pekerjaan: ${alumni.pekerjaan}`,
              html: true
            }
          ]);
        }
      }
    };
    document.addEventListener('click', clickHandler);
    return () => document.removeEventListener('click', clickHandler);
  }, [semuaAlumni]);

const sendMessage = async () => {
  if (!input.trim()) return;

  const pertanyaan = input.trim();
  setMessages(prev => [...prev, { from: 'user', text: pertanyaan }]);
  setInput('');
  setShowMap(false);

  try {
    // 1. Ambil alumniList
    const resList = await fetch('https://hknserver.mapid.co.id/alumni-search', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ question: pertanyaan })
    });
    const { alumniList } = await resList.json();

    // 2. Mulai stream jawaban AI
    const res = await fetch('https://hknserver.mapid.co.id/ask-stream', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ question: pertanyaan })
    });

    const reader = res.body.getReader();
    const decoder = new TextDecoder();
    let done = false;
    let result = '';

    // Tempel pesan awal
    setMessages(prev => [...prev, { from: 'ai', text: '' }]);

    while (!done) {
      const { value, done: doneReading } = await reader.read();
      done = doneReading;
      const chunk = decoder.decode(value);
      result += chunk;
      const resultCopy = result;
      setMessages(prev => [
        ...prev.slice(0, -1),
        { from: 'ai', text: resultCopy  }
      ]);
    }

    // 3. Tambahkan alumniList setelah stream selesai
    setMessages(prev => [
      ...prev.slice(0, -1),
      {
        from: 'ai',
        text: result,
        html: true,
        alumniList
      }
    ]);

    if (alumniList?.length > 0) {
      setMapData(alumniList.slice(0, 20)); // tampilkan hanya yang muncul di card
      setShowMap(true);
    }

  } catch (err) {
    console.error('❌ Gagal kirim:', err);
    setMessages(prev => [
      ...prev,
      { from: 'ai', text: '❌ Gagal mendapatkan jawaban.' }
    ]);
  }
};


  const handleFilterChange = (key, value) => {
    const updated = { ...filter, [key]: value };
    setFilter(updated);

    const hasil = semuaAlumni.filter((a) =>
      (!updated.kota || a.kota === updated.kota) &&
      (!updated.pekerjaan || a.pekerjaan === updated.pekerjaan)
    );

    setMapData(hasil);
    setShowMap(true);
    setMessages(prev => [
      ...prev,
      {
        from: 'ai',
        text: `📋 Filter: ${updated.kota || 'Semua Kota'} – ${updated.pekerjaan || 'Semua Pekerjaan'}\nDitemukan ${hasil.length} alumni.`,
        alumniList: hasil
      }
    ]);
  };

  return (
    <div style={{
      height: '100vh',
      display: 'flex',
      flexDirection: 'column',
      fontFamily: 'sans-serif',
      maxWidth: '480px',
      margin: '0 auto',
      border: '1px solid #eee',
      borderRadius: '8px',
      overflow: 'hidden',
      boxShadow: '0 2px 6px rgba(0,0,0,0.05)',
      backgroundColor: '#fff'
    }}>
      {/* Header */}
      <div style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        padding: '1rem',
        borderBottom: '1px solid #eee'
      }}>
        <button
          onClick={() => onClose ? onClose() : navigate('/dashboard')}
          style={{
            background: 'none',
            border: 'none',
            fontSize: '1.5rem',
            cursor: 'pointer',
            padding: '0 8px'
          }}
        >
          ‹
        </button>
        <h3 style={{ margin: 0, fontWeight: 'bold', flex: 1, textAlign: 'center' }}>Chat With AI</h3>
        <div style={{ width: '24px' }} />
      </div>

      {/* Filter */}
      <div style={{
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        gap: '1rem',
        padding: '0.3rem',
        flexWrap: 'wrap',
        backgroundColor: '#f8f8f8',
        borderBottom: '1px solid #eee'
      }}>
        <div style={{ display: 'flex', flexDirection: 'column' }}>
          <label style={{ fontSize: '0.8rem', marginBottom: '4px' }}>Kota</label>
          <select
              onChange={(e) => handleFilterChange('kota', e.target.value)}
              value={filter.kota}
              style={{
                padding: '6px 10px',
                borderRadius: '8px',
                border: '1px solid #ccc',
                width: '150px' // <-- ukuran tetap
              }}
            >
            <option value="">Semua</option>
            {[...new Set(semuaAlumni.map(a => a.kota))].map((k, i) => (
              <option key={i} value={k}>{k}</option>
            ))}
          </select>
        </div>
        <div style={{ display: 'flex', flexDirection: 'column' }}>
          <label style={{ fontSize: '0.8rem', marginBottom: '4px' }}>Pekerjaan</label>
         <select
              onChange={(e) => handleFilterChange('pekerjaan', e.target.value)}
              value={filter.pekerjaan}
              style={{
                padding: '6px 10px',
                borderRadius: '8px',
                border: '1px solid #ccc',
                width: '150px' // <-- ukuran tetap
              }}
            >
            <option value="">Semua</option>
            {[...new Set(semuaAlumni.map(a => a.pekerjaan))].map((p, i) => (
              <option key={i} value={p}>{p}</option>
            ))}
          </select>
        </div>
      </div>

      {/* Chat Area */}
      <div style={{ flex: 1, padding: '1rem', overflowY: 'auto' }}>
        {messages.map((msg, idx) => (
          <div key={idx} className={`chat-bubble ${msg.from}`}>
            <img
              src={msg.from === 'ai'
                ? AiAvatar
                : 'https://cdn-icons-png.flaticon.com/512/219/219969.png'}
              alt="avatar"
              style={{ width: 32, height: 32, borderRadius: '50%' }}
            />
            <div style={{ display: 'flex', flexDirection: 'column' }}>
              <div
                className="bubble-text"
                dangerouslySetInnerHTML={{
                  __html: msg.html ? msg.text : msg.text.replace(/\n/g, '<br>')
                }}
              />
              {msg.alumniList && (
                <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', marginTop: '0.5rem' }}>
                {(expandedIndexes.includes(idx) ? msg.alumniList : msg.alumniList.slice(0, 20)).map((a, i) => (
                    <div
                      key={i}
                      className="alumni-card"
                      onClick={() => {
                        setMapData([a]);
                        setShowMap(true);
                        setMessages((prev) => [
                          ...prev,
                          {
                            from: 'ai',
                            text: `🧾 Detail Alumni:<br>Nama: <a href="/alumni/${a.id}" target="_blank">${a.nama}</a><br>Kota: ${a.kota}<br>Pekerjaan: ${a.pekerjaan}`,
                            html: true
                          }
                        ]);
                      }}
                      style={{
                        padding: '10px',
                        border: '1px solid #ddd',
                        borderRadius: '8px',
                        cursor: 'pointer',
                        background: '#f9f9f9',
                        transition: 'background 0.2s'
                      }}
                    >
                      <strong>{a.nama}</strong><br />
                      <span style={{ fontSize: '0.85rem', color: '#555' }}>{a.pekerjaan} – {a.kota}</span>
                    </div>
                  ))}
                  
                      {msg.alumniList.length > 20 && !expandedIndexes.includes(idx) && (
  <button
    onClick={() => {
      setExpandedIndexes([...expandedIndexes, idx]);
      setMapData(msg.alumniList); // update map jika diperluas
    }}
    style={{
      marginTop: '8px',
      alignSelf: 'flex-start',
      background: '#eee',
      padding: '6px 12px',
      borderRadius: '6px',
      border: '1px solid #ccc',
      cursor: 'pointer',
      fontSize: '0.9rem'
    }}
  >
    Tampilkan Semua ({msg.alumniList.length})
  </button>
)}

                </div>
              )}
            </div>
          </div>
        ))}

        {/* AlumniMap ditampilkan di luar bubble */}
        {showMap && mapData.length > 0 && (
          <div style={{
            marginTop: '1rem',
            width: '100%',
            height: '300px',
            borderRadius: '8px',
            overflow: 'hidden'
          }}>
            <AlumniMap data={mapData} />
          </div>
        )}
      </div>

      {/* Input */}
      <div style={{ display: 'flex', padding: '1rem', borderTop: '1px solid #eee' }}>
        <input
          type="text"
          placeholder="Tulis pertanyaan..."
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && input.trim() && sendMessage()}
          style={{ flex: 1, padding: '0.75rem', borderRadius: '12px', border: '1px solid #ccc' }}
        />
        <button
          onClick={sendMessage}
          disabled={!input.trim()}
          style={{
            marginLeft: '8px',
            padding: '0.75rem 1rem',
            backgroundColor: input.trim() ? '#facc15' : '#ccc',
            color: input.trim() ? '#000' : '#666',
            border: 'none',
            borderRadius: '12px',
            cursor: input.trim() ? 'pointer' : 'not-allowed'
          }}
        >
          ➤
        </button>
      </div>
    </div>
  );
};

export default Chatbox;
