import React, { useState, useEffect, useRef } from "react";
import axios from "axios";
import "./VerifikasiScreen.css";

const VerifikasiScreen = ({ onBack, onVerified }) => {
  const [otp, setOtp] = useState(["", "", "", "", "", ""]);
  const [error, setError] = useState("");
  const [resendTimer, setResendTimer] = useState(60);
  const [isResendDisabled, setIsResendDisabled] = useState(true);

  const token = localStorage.getItem("jwt");
  const inputRefs = useRef([]);
  const savedPhone = localStorage.getItem("phone_number");
  const formattedPhone = savedPhone ? "+62" + savedPhone.substring(2) : "+62***********";

  useEffect(() => {
  const savedPhone = localStorage.getItem("phone_number");
  console.log("Nomor HP dari localStorage:", savedPhone);
  }, []);

  useEffect(() => {
        let timer;
    if (isResendDisabled && resendTimer > 0) {
      timer = setTimeout(() => setResendTimer((prev) => prev - 1), 1000);
    } else if (resendTimer === 0) {
      setIsResendDisabled(false);
    }
    return () => clearTimeout(timer);
  }, [resendTimer, isResendDisabled]);

  const handleChange = (e, index) => {
    const value = e.target.value.replace(/\D/g, "");
    if (value.length === 0) return;

    const newOtp = [...otp];
    newOtp[index] = value[0];
    setOtp(newOtp);

    if (index < 5) {
      inputRefs.current[index + 1].focus();
    }

    if (error) setError("");
  };

  const handleKeyDown = (e, index) => {
    if (e.key === "Backspace") {
      e.preventDefault();
      const newOtp = [...otp];
      if (otp[index]) {
        newOtp[index] = "";
        setOtp(newOtp);
      } else if (index > 0) {
        inputRefs.current[index - 1].focus();
        const updatedOtp = [...otp];
        updatedOtp[index - 1] = "";
        setOtp(updatedOtp);
      }
    }
  };

  const getFullOtp = () => otp.join("");

  const handleVerify = async () => {
    const rawOtp = getFullOtp();
    if (rawOtp.length !== 6) {
      setError("Kode OTP harus terdiri dari 6 digit.");
      return;
    }

    try {
      await axios.post(
        "https://geoserver.mapid.io/users/verify_otp",
        { otp: rawOtp },
        { headers: { accesstoken: token } }
      );
      alert("OTP berhasil diverifikasi!");
      onVerified(); 
    } catch (err) {
      console.error("Verifikasi OTP gagal:", err);
      setError("Kode OTP salah atau kadaluarsa.");
    }
  };

  const handleResendOtp = async () => {
    try {
      await axios.post(
        "https://geoserver.mapid.io/users/send_otp",
        {},
        { headers: { accesstoken: token } }
      );
      alert("Kode OTP berhasil dikirim ulang.");
      setIsResendDisabled(true);
      setResendTimer(60);
      setOtp(["", "", "", "", "", ""]);
      inputRefs.current[0].focus();
    } catch (error) {
      console.error("Gagal mengirim ulang OTP:", error);
      alert("Gagal mengirim ulang kode OTP.");
    }
  };

  return (
    <div className="verifikasi-container">
      <header className="verifikasi-header">
        <button onClick={onBack} className="back-button">
          <img src="/back.png" alt="Back" />
        </button>
      </header>

      <main className="verifikasi-main">
        <img src="/HKN.png" id="HKN" alt="HKN Logo" />
        <h2>Verifikasi</h2>
          <p>
            Kode telah dikirimkan ke 
            <br/> <span className="phone-number">{formattedPhone}</span>
            <br /> Silakan cek WhatsApp Anda.
          </p>
        <div className="otp-box">
          {otp.map((digit, index) => (
            <input
              key={index}
              type="text"
              maxLength={1}
              value={digit}
              onChange={(e) => handleChange(e, index)}
              onKeyDown={(e) => handleKeyDown(e, index)}
              ref={(el) => (inputRefs.current[index] = el)}
              className="otp-digit"
            />
          ))}
        </div>

        {error && <div className="error-text">{error}</div>}

          <footer className="verifikasi-footer">
            <button
              onClick={handleVerify}
              className={`verifikasi-button ${getFullOtp().length === 6 ? "active" : ""}`}
              disabled={getFullOtp().length !== 6}
            >
              Verifikasi
            </button>

            {isResendDisabled ? (
              <p className="resend-text">Mohon tunggu {resendTimer} detik untuk kirim ulang</p>
            ) : (
              <p className="resend-text">
                Tidak menerima kode?
                <button className="resend-button" onClick={handleResendOtp}>
                  Kirim ulang
                </button>
              </p>
            )}
{/* <button className="skip-button" style={{ display: "none" }}>Lewati Verifikasi</button> */}
          </footer>
      </main>
    </div>
  );
};

export default VerifikasiScreen;
