import React, { useState, useEffect } from "react";
import {
  BrowserRouter as Router,
  Routes,
  Route,
  Navigate,
  useNavigate,
} from "react-router-dom";

import axios from "axios";

// Screens
import SplashScreen from "./components/SplashScreen";
import LoginScreen from "./components/LoginScreen";
import RegisterScreen from "./components/RegisterScreen";
import VerifikasiScreen from "./components/VerifikasiScreen";
import ProfileScreen from "./components/ProfileScreen";
import ForgetPasswordScreen from "./components/ForgetPasswordScreen";
import ForgetPasswordScreen1 from "./components/ForgetPasswordScreen1";
import ForgetPasswordScreen2 from "./components/ForgetPasswordScreen2";
import ForgetPasswordScreen3 from "./components/ForgetPasswordScreen3";
import Dashboardalumni from "./components/Dashboardalumni";
import Chatbox from "./components/Chatboxtemp";
import ProfileAlumni from "./components/ProfileAlumni";
import Home from "./components/Home";
import DetailKegiatan from "./components/DetailKegiatan";
import DataLengkapScreen from "./components/DataLengkapScreen";
import DataLengkapScreen2 from "./components/DataLengkapScreen2";
import DataLengkapScreen3 from "./components/DataLengkapScreen3";
import DataLengkapScreen4 from "./components/DataLengkapScreen4";
import DataLengkapScreen5 from "./components/DataLengkapScreen5";
import UbahSemuaPropertiForm from "./components/UbahSemuaPropertiForm";
import GeometriScreen from "./components/GeometriScreen";

function AppWrapper() {
  const [showSplash, setShowSplash] = useState(true);
  const [screen, setScreen] = useState("login");
  const [prefilledLogin, setPrefilledLogin] = useState({ name: "", password: "", });
  const [forgotData, setForgotData] = useState(null);
  const [verifiedData, setVerifiedData] = useState(null);
  const [geoCoords, setGeoCoords] = useState(null);
  const [formFields, setFormFields] = useState([]);
  const [formDataAll, setFormDataAll] = useState({});
  const navigate = useNavigate();

  useEffect(() => {
    const timer = setTimeout(() => {
      setShowSplash(false);
    }, 3000);
    return () => clearTimeout(timer);
  }, []);

    const fetchFormFields = async () => {
    const storedToken = localStorage.getItem("accessTokenAPI");
    try {
      const res = await axios.get(
        "https://geoserver.mapid.io/moneys_bun/get_layer_detail_by_id/6804f7733996df0058de7279/67fddd3d7df91cc4425c7fba",
        { headers: { accesstoken: storedToken } }
      );
      setFormFields(res.data.fields || []);
    } catch (err) {
      console.error("Gagal mengambil fields:", err);
    }
  };

  const handleLoginSuccess = async (token) => {
    try {
      localStorage.setItem("jwt", token);
      localStorage.setItem("accessTokenAPI", "eyJhbGciOiJIUzI1NiJ9.eyJ1c2VyX2lkIjoiNjdhZjExMTYwZWNjNTEyNTgyMTI1ZjM2IiwidXNlcm5hbWUiOiJsb2thdmF0YV9ndXN0aWF5dW1hZGUifQ.uSPJW2ItArtNGO4E-Rp-Bl8P1miyxlTY8SG4YHmcGG4");

      const userResponse = await axios.get("https://geoserver.mapid.io/users/", {
        headers: {
          accesstoken: token,
        },
      });

      localStorage.setItem("user", JSON.stringify(userResponse.data));


      const isConfirmed = userResponse?.data?.is_whatsapp_confirm === "success";

      if (isConfirmed) {
        await fetchFormFields();
        navigate("/home");
      } else {
        await axios.post(
          "https://geoserver.mapid.io/users/send_otp",
          {},
          { headers: { accesstoken: token } }
        );
        setScreen("verifikasi");
      }

    } catch (error) {
      console.error("Login lanjut gagal:", error);
      alert("Terjadi kesalahan saat verifikasi login.");
    }
  };


  const handleSendOtpSuccess = (data) => {
    setForgotData(data);
    setScreen("forget2");
  };

  const handleOtpVerified = (data) => {
    setVerifiedData(data);
    setScreen("forget3");
  };

  if (showSplash) return <SplashScreen />;

  // Kendali non-router (khusus OTP / lupa password)
  if (screen === "verifikasi") {
    return (
      <VerifikasiScreen
        onBack={() => setScreen("login")}
        onVerified={() => setScreen("geo")}
      />
    );
  }

  if (screen === "forget") {
    return (
      <ForgetPasswordScreen1
        onBack={() => setScreen("login")}
        onSendOtpSuccess={handleSendOtpSuccess}
      />
    );
  }

  if (screen === "forget2") {
    return (
      <ForgetPasswordScreen2
        data={forgotData}
        onBack={() => setScreen("forget")}
        onVerified={handleOtpVerified}
      />
    );
  }

  if (screen === "forget3") {
  return (
    <ForgetPasswordScreen3
      data={verifiedData}
      onBack={() => setScreen("forget2")}
      onDone={() => {
        setScreen(null);       // ini WAJIB untuk keluar dari mode screen manual
        navigate("/");         // arahkan ke login
      }}
    />
  );
}

  if (screen === "forgetProfile") {
    return (
      <ForgetPasswordScreen
        onBack={() => setScreen("profile")}
        onSendOtpSuccess={handleSendOtpSuccess}
      />
    );
  }

  if (screen === "detail"){
    return (
      <DataLengkapScreen
        fields={formFields}
        formDataAll={formDataAll}
        setFormDataAll={setFormDataAll}
        onBack={() => setScreen("geo")}
        onNext={() => setScreen("detail2")}
        coords={geoCoords}
        goToSection={(num) => {
          const section = Number(num);
          if (section === 1) setScreen("detail");
          else if (section === 2) setScreen("detail2");
          else if (section === 3) setScreen("detail3");
          else if (section === 4) setScreen("detail4"); 
          else if (section === 5) setScreen("detail5"); 
          else setScreen("profile");
        }}
      />
    )
  }

  if (screen === "detail2"){
    return(
      <DataLengkapScreen2
        coords={geoCoords}
        fields={formFields}
        formDataAll={formDataAll}
        setFormDataAll={setFormDataAll}
        onBack={() => setScreen("detail")}
        onNext={() => setScreen("detail3")}
        goToSection={(num) => {
          const section = Number(num);
          if (section === 1) setScreen("detail");
          else if (section === 2) setScreen("detail2");
          else if (section === 3) setScreen("detail3");
          else if (section === 4) setScreen("detail4"); 
          else if (section === 5) setScreen("detail5"); 
          else setScreen("profile");
        }}
      />
    )
  }

  if (screen === "detail3"){
    return(
      <DataLengkapScreen3
        coords={geoCoords}
        fields={formFields}
        formDataAll={formDataAll}
        setFormDataAll={setFormDataAll}
        onBack={() => setScreen("detai2")}
        onNext={() => setScreen("detail4")}
        goToSection={(num) => {
          const section = Number(num);
          if (section === 1) setScreen("detail");
          else if (section === 2) setScreen("detail2");
          else if (section === 3) setScreen("detail3"); 
          else if (section === 4) setScreen("detail4"); 
          else if (section === 5) setScreen("detail5"); 
          else setScreen("profile");
        }}
      />
    )
  }

    if (screen === "detail4"){
    return(
      <DataLengkapScreen4
        coords={geoCoords}
        fields={formFields}
        formDataAll={formDataAll}
        setFormDataAll={setFormDataAll}
        onBack={() => setScreen("detai3")}
        onNext={() => setScreen("detail5")}
        goToSection={(num) => {
          const section = Number(num);
          if (section === 1) setScreen("detail");
          else if (section === 2) setScreen("detail2");
          else if (section === 3) setScreen("detail3"); 
          else if (section === 4) setScreen("detail4"); 
          else if (section === 5) setScreen("detail5"); 
          else setScreen("profile");
        }}
      />
    )
  }

    if (screen === "detail5"){
      return(
        <DataLengkapScreen5
          coords={geoCoords}
          fields={formFields}
          formDataAll={formDataAll}
          setFormDataAll={setFormDataAll}
          onBack={() => setScreen("detai4")}
          onSuccess={() => {setScreen(null); navigate("/home")}}
          goToSection={(num) => {
            const section = Number(num);
            if (section === 1) setScreen("detail");
            else if (section === 2) setScreen("detail2");
            else if (section === 3) setScreen("detail3"); 
            else if (section === 4) setScreen("detail4"); 
            else if (section === 5) setScreen("detail5"); 
            else setScreen("profile");
          }}
        />
      )
  }

  if (screen === "geo"){
    return(
      <GeometriScreen
      onBack={() => setScreen("profile")}
      onSave={(coords) => {
        setGeoCoords(coords);
        setScreen("detail");
      }}
      />
    )
  }


  return (
    <Routes>
      <Route path="/" element={
        <LoginScreen
          onRegister={() => navigate("/register")}
          onLoginSuccess={handleLoginSuccess}
          onForgetPassword={() => setScreen("forget")}
          prefilledLogin={prefilledLogin}
        />
      } />
      <Route path="/register" element={
        <RegisterScreen
          onBackToLogin={() => navigate("/")}
          onRegisterSuccess={(data) => {
            setPrefilledLogin(data);
            localStorage.setItem("full_name", data.full_name)
            localStorage.setItem("username", data.name)
            localStorage.setItem("phone_number", data.phone_number)
            navigate("/");
          }}
        />
      } />
      <Route path="/profile" element={<ProfileScreen onChange={() => setScreen("forget")} onData={() => navigate("/ubah-semua-properti")}/>} />
      <Route path="/dashboard" element={<Dashboardalumni />} />
      <Route path="/home" element={<Home />} />
      <Route path="/chat" element={<Chatbox />} />
      <Route path="/alumni/:id" element={<ProfileAlumni />} />
      <Route path="/kegiatan/:id" element={<DetailKegiatan />} />
      <Route path="/ubah-semua-properti" element={<UbahSemuaPropertiForm />} />
      <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
  );
}

export default function App() {
  return (
    <Router>
      <AppWrapper />
    </Router>
  );
}
